\label{thmmain}
Let $u_0$ be real-valued and assume that one of the following two conditions holds:
\begin{enumerate}
\item $\langle X\rangle^{\frac12}u_0\in B^2_{1,1}(\mathbb{R}^2)$;
\item $u_0\in L^2(\mathbb{R}^2)$ and $\langle X\rangle u_0\in B^{s_1,s_2}_{1,1}(\mathbb{R}^2)$ for some $s_1>0$, $s_2>0$ with $s_1+2s_2>3$.
\end{enumerate}
Let $u\in C(\mathbb{R};L^2(\mathbb{R}^2))$ be the solution of \eqref{kp}. Then there exist $u_+,u_-\in L^2(\mathbb{R}^2)$ such that
\begin{equation}
\label{scattering}
\lim_{t\to\pm\infty}\|u(t)-S(t)u_\pm\|_{L^2}=0 .
\end{equation}

\label{corexamples}
The conclusion of Theorem \ref{thmmain} holds for each of the following real initial data:
\begin{enumerate}
\item every Schwartz function $u_0$;
\item every $u_0$ with $\langle X\rangle u_0\in W^{r,1}(\mathbb{R}^2)$ for some $r>\frac32$;
\item $u_0(x,y)=\1_{[0,1]}(x)g(y)$ and $u_0(x,y)=g(x)\1_{[0,1]}(y)$, for every real $g\in C^\infty_c(\mathbb{R})$, of arbitrary size.
\end{enumerate}

\label{lemmacauchy}
\begin{enumerate}
\item {\em (Modulus of continuity).} Let $f$ be measurable with $\|f\|_\infty+\|\mathcal{I}|f|\|_\infty<\infty$. Then $\mathcal{C} f$ and $\mathcal{I}|f|$ are continuous, and for $k,h\in\mathbb{C}$ with $0<|h|\le\frac12$,
\begin{equation}
\label{cauchymodulus}
\begin{aligned}
&|\mathcal{C} f(k+h)-\mathcal{C} f(k)|+\big|\mathcal{I}|f|(k+h)-\mathcal{I}|f|(k)\big|\\
&\qquad\lesssim|h|\log\frac1{|h|}\big(\|f\|_\infty+\|\mathcal{I}|f|\|_\infty\big).
\end{aligned}
\end{equation}
\item {\em (Inversion of $\bar\partial$).} Let $f$ be as in (i). Then $\bar\partial\,\mathcal{C} f=f$ in $\mathcal D'(\mathbb{C})$. If moreover $\mathcal{I}|f|\in C_0(\mathbb{C})$ and $v\in C_0(\mathbb{C})$ satisfies $\bar\partial v=f$ in $\mathcal D'(\mathbb{C})$, then $v=\mathcal{C} f$.
\item {\em (Potentials of sets).} For a disc $D$ of radius $r$, an axis-parallel rectangle $Q$ with sides $L_1,L_2$, and a nonnegative $g\in L^1\cap L^\infty(\mathbb{C})$,
\begin{equation}
\label{potentialsets}
\begin{gathered}
\mathcal{I}\1_D\le2r,\qquad \mathcal{I}\1_Q\lesssim\min(L_1,L_2)\Big(1+\Big|\log\frac{L_1}{L_2}\Big|\Big),\\
\|\mathcal{I} g\|_\infty\le2\big(\|g\|_\infty\|g\|_{L^1}\big)^{\frac12}\le\|g\|_\infty+\|g\|_{L^1},
\end{gathered}
\end{equation}
and moreover $\mathcal{I} g\in C_0(\mathbb{C})$.
\item {\em (Domination).} Let $F\ge0$ be bounded on bounded sets, with $\mathcal{I} F\in C_0(\mathbb{C})$. Then $\sup_{k}\mathcal{I}(F\1_{\{|k'|>R\}})(k)\to0$ as $R\to\infty$, and $\mathcal{I} G\in C_0(\mathbb{C})$ for every measurable $G$ with $0\le G\le F$.
\item {\em (Convergence).} Let $F$ be as in (iv), and moreover bounded. Then $\sup_k\mathcal{I}(F\1_{\{|k'_2|<\varepsilon\}})(k)\to0$ as $\varepsilon\to0$, and every sequence $(f_n)$ with $|f_n|\le F$ which tends to zero uniformly on the compact subsets of $\mathbb{C}\setminus\mathbb{R}$ satisfies $\|\mathcal{I}|f_n|\|_\infty\to0$.
\item {\em (Integration by parts).} Let $\phi\in C^2(\mathbb{C})$ be real, and let $f\in C^1(\mathbb{C})$ be such that $\bar\partial\phi\neq0$ on the support of $f$, $\frac f{\bar\partial\phi}\in C_0(\mathbb{C})$, and $f$ and $\bar\partial\big(\frac f{\bar\partial\phi}\big)$ belong to $L^1\cap L^\infty(\mathbb{C})$. Then
\begin{equation}
\label{ibp}
\mathcal{C}\big(e^{i\phi}f\big)=\frac{e^{i\phi}f}{i\bar\partial\phi}-\mathcal{C}\Big(e^{i\phi}\,\bar\partial\Big(\frac f{i\bar\partial\phi}\Big)\Big).
\end{equation}
\end{enumerate}

\label{lemmavekua}
Let $a\in L^\infty(\mathbb{C})$ with $\mathcal{I}|a|\in C_0(\mathbb{C})$, and set $M:=\|\mathcal{I}|a|\|_\infty$.
\begin{enumerate}
\item {\em (Unique solvability).} For every $f\in L^\infty(\mathbb{C})$ with $\mathcal{I}|f|\in C_0(\mathbb{C})$, there is a unique $v\in C_0(\mathbb{C})$ such that
\begin{equation}
\label{eqvekua}
v=\mathcal{C} f+\mathcal{C}(a\overline v),
\end{equation}
and it satisfies, for every $k\in\mathbb{C}$,
\begin{equation}
\label{pointwisevekua}
|v(k)|\le e^{2M}\,\mathcal{I}|f|(k).
\end{equation}
Moreover, every $v'\in C_0(\mathbb{C})$ with $\bar\partial v'=a\overline{v'}+f$ in $\mathcal D'(\mathbb{C})$ coincides with $v$.
\item {\em (Eigenfunction).} The equation $m=1+\mathcal{C}(a\overline m)$ has a unique solution $m\in C_b(\mathbb{C})$. It satisfies $m-1\in C_0(\mathbb{C})$ and
\begin{equation}
\label{boundeigen}
|m(k)-1|\le e^{2M}\mathcal{I}|a|(k),\qquad \|m\|_\infty\le1+Me^{2M}.
\end{equation}
\item {\em (Bounded right-hand side).} For every $b\in C_b(\mathbb{C})$, the equation $v=b+\mathcal{C}(a\overline v)$ has a unique solution $v\in C_b(\mathbb{C})$, and $\|v\|_\infty\le(1+Me^{2M})\|b\|_\infty$.
\item {\em (Comparison).} If $a_1,a_2$ satisfy the assumptions of the lemma, with constants $M_1,M_2$ and eigenfunctions $m_1,m_2$ given by (ii), then
\begin{equation}
\label{comparison}
\|m_1-m_2\|_\infty\le e^{2M_1}(1+M_2e^{2M_2})\,\|\mathcal{I}|a_1-a_2|\|_\infty .
\end{equation}
\item {\em (Regularity).} The solutions given by (i), and by (iii) when $b$ is constant, belong to $W^{1,p}_{\rm loc}(\mathbb{C})$ for every $p\in(2,\infty)$.
\end{enumerate}

\label{lemmaweights}
\begin{enumerate}
\item {\em (Anisotropic weights).} Let $\alpha>0$ and $0<\beta<1$ with $\alpha+2\beta>2$, and $F:=F_{\alpha,\beta}$. Then
\begin{equation}
\label{weightsF}
\mathcal{I} F,\ \mathcal{I}(|k_2|F)\in C_0(\mathbb{C}),\qquad \int_\mathbb{C}\frac{(1+|k_2|)F}{\langle k\rangle}\,dA<\infty .
\end{equation}
\item {\em (Rapidly decaying weights).} The functions $\mathcal{I}\langle \zeta\rangle^{-6}$ and $\mathcal{I}(|k_2|\langle \zeta\rangle^{-6})$ belong to $C_0(\mathbb{C})$, and
\begin{equation}
\label{weightsE}
\begin{gathered}
\int_\mathbb{C}\Big(|k_2|+k_2^2+\frac1{\langle k\rangle}\Big)\langle \zeta(k)\rangle^{-6}dA(k)<\infty,\\
\mathcal{I}\big((|k_2|+k_2^2)\langle \zeta\rangle^{-6}\big)(k)\lesssim\langle k\rangle^{-1}.
\end{gathered}
\end{equation}
\item {\em (Tails).} For $R\ge1$,
\begin{equation}
\label{weightstail}
\sup_{k\in\mathbb{C}}\mathcal{I}\big(\langle \zeta\rangle^{-6}\1_{\{|k'|>R\}}\big)(k)\lesssim\frac{1+\log R}R .
\end{equation}
\end{enumerate}

\label{lemmainverse}
Let $a$ satisfy \eqref{hypa}. Then $M:=\|\mathcal{I}|a|\|_\infty<\infty$, and for every $(t,X)$ the equation \eqref{eqm} has a unique solution $m(\cdot;t,X)\in C_b(\mathbb{C})$. Moreover:
\begin{enumerate}
\item $\|m(\cdot;t,X)\|_\infty\le1+Me^{2M}$ and $m(\bar k;t,X)=\overline{m(k;t,X)}$;
\item $m$ is twice differentiable in $x$ as a $C_b(\mathbb{C})$-valued function, $\partial_xm$ is the solution in $C_0(\mathbb{C})$ of
\begin{equation}
\label{eqmx}
\partial_xm=\mathcal{C}(aP\overline{\partial_xm})+\mathcal{C}(-2ik_2aP\overline m),
\end{equation}
and $|\partial_xm(k;t,X)|+|\partial_x^2m(k;t,X)|\lesssim\langle k\rangle^{-1}$ uniformly in $(t,X)$;
\item the integral \eqref{reconstruction} converges absolutely, $u$ and $\partial_xu$ are real-valued, bounded and continuous on $\mathbb{R}\times\mathbb{R}^2$, and \eqref{remainder} holds;
\item {\em (Cancellation).} $m$ and $\partial_xm$ belong to $W^{1,p}_{\rm loc}(\mathbb{C})$ for every $p\in(2,\infty)$, and the function $B$ of \eqref{remainder} satisfies
\begin{equation}
\label{cancellation}
\partial_kB=-\overline{(m-1)}+\overline{aP}\,\partial_xm .
\end{equation}
\end{enumerate}

\label{lemmafree}
Let $\hat\varphi\in C^\infty_c(\{\xi\neq0\})$, and let $V\subset\mathcal{V}$ be a compact set whose interior contains the set of group velocities $\{-\nabla\omega(\xi,\eta):\ (\xi,\eta)\in\operatorname{supp}\hat\varphi\}$. Then
\begin{equation}
\label{freecones}
\|S(t)\varphi\|_{L^1}\lesssim1+|t|,\qquad \lim_{|t|\to\infty}\big\|\1_{\{X/t\notin V\}}S(t)\varphi\big\|_{L^2}=0 .
\end{equation}

\label{lemmaweak}
Let $u_n\in C(\mathbb{R};L^2(\mathbb{R}^2))$ and $g_n\in L^2(\mathbb{R}^2)$, $n\ge1$, with $\sup_{n,t}\|u_n(t)\|_{L^2}+\sup_n\|g_n\|_{L^2}<\infty$. Assume that
\begin{enumerate}
\item for every $t$, $u_n(t)\rightharpoonup u(t)$ in $L^2$, and $g_n\rightharpoonup g$ in $L^2$;
\item for every compact set $V\subset\mathcal{V}$,
\begin{equation}
\label{hypcone}
\lim_{|t|\to\infty}\ \sup_{n\ge1}\ \sup_{X/t\in V}\ |t|\,\big|u_n(t,X)-S(t)g_n(X)\big|=0,
\end{equation}
where the supremum in $X$ is an essential supremum.
\end{enumerate}
Then $S(-t)u(t)\rightharpoonup g$ in $L^2$ as $t\to\pm\infty$. If moreover $\|u(t)\|_{L^2}=\|g\|_{L^2}$ for every $t$, then $\|u(t)-S(t)g\|_{L^2}\to0$ as $t\to\pm\infty$.

\label{lemmaphase}
Let $V\subset\mathcal{V}$ be compact. There are constants $0<c_V\le1\le C_V$ such that the following holds for $t\neq0$, $X=tv$, $v\in V$.
\begin{enumerate}
\item $\partial_k\phi(k;t,X)=-12it\,(k-k_+(v))(k-k_-(v))$. The points $k_\pm(v)$ are the only critical points of $\phi(\cdot;t,X)$, and they satisfy $|k_\pm(v)|\le C_V$ and $\pm\operatorname{Im} k_\pm(v)\ge c_V$.
\item For all $k\in\mathbb{C}$, $|\partial_k^2\phi(k)|\le C_V|t|\langle k\rangle$; for every $r>0$ there is $c_{V,r}>0$ such that $|\partial_k\phi(k)|\ge c_{V,r}|t|\langle k\rangle^2$ whenever $|k-k_+(v)|\ge r$ and $|k-k_-(v)|\ge r$; and on the real axis, $|\partial_k\phi(k_1)|\ge c_V|t|(1+k_1^2)$.
\item In the real coordinates $(k_1,k_2)$, the Hessian matrix of $\phi$ at $k_\pm(v)$ is $48\,t\,\operatorname{Im} k_\pm(v)\begin{pmatrix}1&0\\0&-1\end{pmatrix}$.
\end{enumerate}

\label{propcone}
Let $(a_n)_{n\ge1}$ be a family of coefficients which satisfy \eqref{hypa}, let $u_n$ be the functions given by \eqref{reconstruction} with $a=a_n$, and $g_n:=\mathcal{B} a_n$. Assume that there is a function $F\in L^\infty(\mathbb{C})$ which satisfies the conditions \eqref{weightsF} of Lemma \ref{lemmaweights} (i), and such that, for all $n$ and $k\in\mathbb{C}\setminus\mathbb{R}$,
\begin{equation}
\label{hypF1}
|a_n(k)|\le F(k),\qquad |\nabla_ka_n(k)|\le\langle k\rangle F(k).
\end{equation}
Then \eqref{hypcone} holds for every compact set $V\subset\mathcal{V}$.

Fix $V$, and let $|t|\ge1$ and $v=X/t\in V$. All constants below depend on $V$ and $F$, but not on $n$, $t$ and $X$. We write $m_n$ for the eigenfunction of $a_n$, $M:=\|\mathcal{I} F\|_\infty$ and $M':=\|\mathcal{I}(|k_2|F)\|_\infty$. The decay \eqref{hypa} of each $a_n$ is used only to justify the computations qualitatively, through Lemma \ref{lemmainverse}.\\

\noindent{\bf Step 1:} Uniform bounds. By Lemma \ref{lemmavekua}, whose bounds depend on $|a_nP|\le F$ only, $\|m_n\|_\infty\le1+Me^{2M}$. By \eqref{eqmx} and \eqref{pointwisevekua}, $\|\partial_xm_n\|_\infty\le2e^{2M}(1+Me^{2M})M'$. Hence $\|m_n\|_\infty+\|\partial_xm_n\|_\infty\lesssim1$.\\

\noindent{\bf Step 2:} Smallness of the eigenfunctions. We claim that $\varepsilon(t)\to0$ as $|t|\to\infty$, where
\begin{equation}
\label{defepst}
\varepsilon(t):=\sup_{n\ge1}\ \sup_{X/t\in V}\Big(\|m_n(\cdot;t,X)-1\|_\infty+\|\partial_xm_n(\cdot;t,X)\|_\infty\Big).
\end{equation}
By \eqref{eqm}, $m_n-1=\mathcal{C}(a_nP)+\mathcal{C}\big(a_nP\overline{(m_n-1)}\big)$, and by \eqref{eqmx}, $\partial_xm_n=\mathcal{C}(a_nP\overline{\partial_xm_n})+b_n$ with $b_n:=\mathcal{C}(-2ik_2a_nP)+\mathcal{C}\big(-2ik_2a_nP\overline{(m_n-1)}\big)$, where $\|b_n\|_\infty\le2\|\mathcal{C}(k_2a_nP)\|_\infty+2M'\|m_n-1\|_\infty$. Lemma \ref{lemmavekua} (iii) gives
$$\|m_n-1\|_\infty+\|\partial_xm_n\|_\infty\lesssim\|\mathcal{C}(a_nP)\|_\infty+\|\mathcal{C}(k_2a_nP)\|_\infty,$$
so that $\varepsilon(t)\to0$ follows from the oscillatory estimate
\begin{equation}
\label{oscillatory}
\lim_{|t|\to\infty}\ \sup_{n\ge1}\ \sup_{X/t\in V}\ \|\mathcal{C}(c_nP)\|_\infty=0,\qquad c_n\in\{a_n,\ k_2a_n\}.
\end{equation}
To prove \eqref{oscillatory}, let $F_1:=(1+|k_2|)F$, which satisfies $|c_n|\le F_1$, $\mathcal{I} F_1\in C_0$, and is bounded on bounded sets. Let $\delta>0$. By Lemma \ref{lemmacauchy} (iv) and \eqref{potentialsets} we can choose $R\ge C_V+1$ and then $r_1\in(0,\frac{c_V}2)$ such that
$$\sup_{k\in\mathbb{C}}\mathcal{I}(F_1\1_{\{|k'|>R\}})(k)+\sup_{k\in\mathbb{C}}\mathcal{I}(F_1\1_{\{|k'|\le2R,\,|k_2'|<2r_1\}})(k)+8r_1\sup_{|k'|\le2R}F_1(k')\le\delta .$$
Let $\vartheta_*\in C^\infty(\mathbb{C})$ with $0\le\vartheta_*\le1$, $\vartheta_*=1$ on $\{|k|\le R,\ |k_2|\ge2r_1\}\setminus\big(D(k_+,2r_1)\cup D(k_-,2r_1)\big)$, $\vartheta_*=0$ outside $\{|k|\le2R,\ |k_2|\ge r_1\}\setminus\big(D(k_+,r_1)\cup D(k_-,r_1)\big)$, and $|\nabla\vartheta_*|\lesssim_{R,r_1}1$; such a function is obtained from fixed cutoffs translated with $k_\pm(v)$. Then $1-\vartheta_*$ is bounded by the sum of the indicator functions of the four sets $\{|k|>R\}$, $\{|k|\le2R,|k_2|<2r_1\}$ and $D(k_\pm,2r_1)$, the last two of which are contained in $\{|k|\le2R\}$ since $R\ge C_V+1$, and \eqref{potentialsets} gives $\|\mathcal{C}((1-\vartheta_*)c_nP)\|_\infty\le\mathcal{I}(F_1(1-\vartheta_*))\le\delta$. On the support of $\vartheta_*$ we have $|\bar\partial\phi|=|\partial_k\phi|\ge12|t|r_1^2$ and $|\nabla_k\bar\partial\phi|\lesssim_R|t|$, while $f:=\vartheta_*c_n$ satisfies $\|f\|_\infty+\|\nabla f\|_\infty\lesssim_{R,r_1}1$ by \eqref{hypF1}. Since $f\in C^1(\mathbb{C})$ has compact support, Lemma \ref{lemmacauchy} (vi) and \eqref{potentialsets} give
$$\|\mathcal{C}(Pf)\|_\infty\le\Big\|\frac f{\bar\partial\phi}\Big\|_\infty+\Big\|\mathcal{I}\Big|\bar\partial\frac f{\bar\partial\phi}\Big|\Big\|_\infty\lesssim_{R,r_1}\frac1{|t|}.$$ Therefore $\limsup_{|t|\to\infty}\sup_n\sup_{X/t\in V}\|\mathcal{C}(c_nP)\|_\infty\le\delta$ for every $\delta>0$, which proves \eqref{oscillatory}.\\

\noindent{\bf Step 3:} The remainder and its cancellation. By \eqref{remainder},
\begin{equation}
\label{remainderfn}
\begin{gathered}
u_n(t,X)-S(t)g_n(X)=-\frac2\pi\int_\mathbb{C} f_n\,P\,dA,\\
f_n:=a_nB_n,\qquad B_n:=-2ik_2\overline{(m_n-1)}+\overline{\partial_xm_n}.
\end{gathered}
\end{equation}
By Lemma \ref{lemmainverse} (iv), $B_n\in W^{1,p}_{\rm loc}(\mathbb{C})$ for $p<\infty$ and $\partial_kB_n=-\overline{(m_n-1)}+\overline{a_nP}\,\partial_xm_n$. By \eqref{defepst} and \eqref{hypF1},
\begin{equation}
\label{boundfn}
\begin{gathered}
|B_n|\le2(1+|k_2|)\varepsilon(t),\qquad |\partial_kB_n|\lesssim\varepsilon(t),\\
|f_n|\le2(1+|k_2|)F\varepsilon(t),\qquad |\partial_kf_n|\lesssim(1+|k_2|)\langle k\rangle F\varepsilon(t),
\end{gathered}
\end{equation}
where $\partial_kf_n$ is a locally bounded function on $\mathbb{C}\setminus\mathbb{R}$.\\

\noindent{\bf Step 4:} Contribution of the critical points. By \eqref{boundfn}, $|f_n|+|\partial_kf_n|\lesssim\varepsilon(t)$ on the discs $D(k_\pm,4r_0)$. Fix $p\in(2,\infty)$ and $\sigma:=1-\frac2p$. For $q\in W^{1,p}(D(k_\pm,4r_0))$ we have the interior estimate
$$\|\nabla q\|_{L^p(D(k_\pm,2r_0))}\lesssim\|\partial_kq\|_{L^p(D(k_\pm,4r_0))}+\|q\|_{L^p(D(k_\pm,4r_0))}:$$
indeed, with $\vartheta_2(k):=\vartheta(\frac{k-k_\pm}{2r_0})$, which equals $1$ on $D(k_\pm,2r_0)$ and is supported in $D(k_\pm,4r_0)$, Lemma \ref{lemmacauchy} (ii), applied to smooth functions and extended by density to compactly supported $W^{1,p}$ functions, gives $\overline{\vartheta_2q}=\mathcal{C}\big(\overline{\partial_k(\vartheta_2q)}\big)$; hence $\overline{\bar\partial(\vartheta_2q)}=\partial_k\mathcal{C}\big(\overline{\partial_k(\vartheta_2q)}\big)$, and $\partial_k\mathcal{C}$ is the Beurling transform, which is bounded on $L^p$ \cite{Stein}. Applied to $q=f_n$, this gives $\|f_n\|_{W^{1,p}(D(k_\pm,2r_0))}\lesssim\varepsilon(t)$, and Morrey's inequality gives
\begin{equation}
\label{morrey}
|f_n(k)-f_n(k_\pm)|\lesssim\varepsilon(t)|k-k_\pm|^\sigma\qquad\mbox{for}\ k\in D_\pm .
\end{equation}
Let $\vartheta_\pm(k):=\vartheta(\frac{2(k-k_\pm)}{r_0})$, which equals $1$ on $D(k_\pm,\frac{r_0}2)$ and is supported in $D_\pm$, and write $\vartheta_\pm f_n=f_n(k_\pm)\vartheta_\pm+h_\pm$ with $h_\pm:=\vartheta_\pm\big(f_n-f_n(k_\pm)\big)$. By Lemma \ref{lemmaphase} (iii), $\phi/t$ has a nondegenerate critical point at $k_\pm$, with Hessian determinant bounded away from zero uniformly in $v\in V$, and no other critical point on the support of $\vartheta_\pm$. The stationary phase estimate \cite[Theorem 7.7.5]{Hormander} gives $|\int\vartheta_\pm P\,dA|\lesssim|t|^{-1}$, so that the first part contributes $O(\varepsilon(t)|t|^{-1})$. For the second part, let $\rho:=|t|^{-\frac12}$, assume $|t|$ so large that $2\rho<\frac{r_0}2$, and let $\vartheta_\rho(k):=\vartheta\big(\frac{k-k_\pm}\rho\big)$. By \eqref{morrey},
$$\Big|\int_\mathbb{C} h_\pm\vartheta_\rho P\,dA\Big|\lesssim\varepsilon(t)\int_{D(k_\pm,2\rho)}|k-k_\pm|^\sigma\,dA\lesssim\varepsilon(t)\rho^{2+\sigma}\le\varepsilon(t)|t|^{-1}.$$
On the support of $h_\pm(1-\vartheta_\rho)$ we integrate by parts with $\partial_kP=i(\partial_k\phi)P$; there are no boundary terms, since this function is compactly supported in $D_\pm\setminus D(k_\pm,\rho)$:
$$\int_\mathbb{C} h_\pm(1-\vartheta_\rho)P\,dA=-\int_\mathbb{C} P\,\partial_k\Big(\frac{h_\pm(1-\vartheta_\rho)}{i\partial_k\phi}\Big)dA .$$
On $D_\pm$, Lemma \ref{lemmaphase} gives $|\partial_k\phi|\gtrsim|t||k-k_\pm|$ and $|\partial_k^2\phi|\lesssim|t|$. Since $|\partial_kh_\pm|\lesssim\varepsilon(t)$ by \eqref{boundfn}, the derivative of $h_\pm$ contributes at most $\frac{C\varepsilon(t)}{|t|}\int_{D_\pm}\frac{dA}{|k-k_\pm|}\lesssim\frac{\varepsilon(t)}{|t|}$. By \eqref{morrey}, the derivative of $(\partial_k\phi)^{-1}$ contributes at most $\frac{C\varepsilon(t)}{|t|}\int_{D_\pm}|k-k_\pm|^{\sigma-2}\,dA\lesssim\frac{\varepsilon(t)}{|t|}$, and the derivative of $\vartheta_\rho$, which is bounded by $C\rho^{-1}$ and supported in $\{\rho\le|k-k_\pm|\le2\rho\}$, contributes at most $\frac C{|t|}\varepsilon(t)\rho^\sigma\rho^{-2}\rho^2\lesssim\frac{\varepsilon(t)}{|t|}$. Hence each critical point contributes $O(\varepsilon(t)|t|^{-1})$ to \eqref{remainderfn}.\\

\noindent{\bf Step 5:} Contribution of the rest of the plane. Let $f_n^0:=f_n(1-\vartheta_+-\vartheta_-)$. On its support, $|k-k_\pm|\ge\frac{r_0}2$ and, by Lemma \ref{lemmaphase} (ii) with $r=\frac{r_0}2$, $|\partial_k\phi|\gtrsim|t|\langle k\rangle^2$ and $|\partial_k^2\phi|\lesssim|t|\langle k\rangle$. For each fixed $n$, \eqref{hypa}, Lemma \ref{lemmainverse} (ii) and \eqref{weightsE} give $|f_n|\lesssim_n(|k_2|+\langle k\rangle^{-1})\langle \zeta\rangle^{-6}\in L^1(\mathbb{C})$, so that $\int f_n^0P\,dA=\lim_{L\to\infty}\int f_n^0\vartheta_LP\,dA$, where $\vartheta_L(k):=\vartheta(k/L)$. We integrate by parts separately in $\mathbb{C}^+$ and in $\mathbb{C}^-$, using Green's formula $\int_{\mathbb{C}^\pm}\partial_kG\,dA=\mp\frac1{2i}\int_\mathbb{R} G^\pm\,dk_1$ for compactly supported $G$ which are continuous up to the boundary. With $G=\frac{f^0_n\vartheta_LP}{i\partial_k\phi}$ and $P=1$ on $\mathbb{R}$, this gives
$$\int_\mathbb{C} f_n^0\vartheta_LP\,dA=-\int_{\mathbb{C}\setminus\mathbb{R}}P\,\partial_k\Big(\frac{f_n^0\vartheta_L}{i\partial_k\phi}\Big)dA-\frac1{2i}\int_\mathbb{R}\frac{f_n^+-f_n^-}{i\partial_k\phi}\,\vartheta_L\,dk_1 .$$
On the real axis $k_2=0$, so that $B_n=\overline{\partial_xm_n}$, which is continuous across the axis, and $f_n^\pm=a_n^\pm\overline{\partial_xm_n}$ is bounded by $\|F\|_\infty\varepsilon(t)$. Together with $|\partial_k\phi(k_1)|\gtrsim|t|(1+k_1^2)$, the boundary term is bounded by $C\varepsilon(t)|t|^{-1}\int_\mathbb{R}\frac{dk_1}{1+k_1^2}$. In the bulk term, the derivative falls on $f_n$, on the fixed cutoffs $\vartheta_\pm$, on $\vartheta_L$ or on $(\partial_k\phi)^{-1}$; by \eqref{boundfn} and the bounds on $\partial_k\phi$, the integrand is bounded by
$$\frac{C\varepsilon(t)}{|t|}\Big(\frac{\langle k\rangle F_1}{\langle k\rangle^2}+F_1\1_{\{|k|\le C\}}+\frac{F_1\1_{\{L\le|k|\le2L\}}}{L\langle k\rangle^2}+\frac{\langle k\rangle F_1}{\langle k\rangle^4}\Big)\lesssim\frac{\varepsilon(t)}{|t|}\frac{F_1}{\langle k\rangle},$$
which is integrable by \eqref{weightsF}, uniformly in $L$. Letting $L\to\infty$, the term containing $\nabla\vartheta_L$ tends to zero, and we obtain $|\int f_n^0P\,dA|\lesssim\varepsilon(t)|t|^{-1}$.\\

\noindent{\bf Step 6:} Conclusion. Steps 4 and 5 give $\sup_n\sup_{X/t\in V}|u_n(t,X)-S(t)g_n(X)|\lesssim\varepsilon(t)|t|^{-1}$, and $\varepsilon(t)\to0$ proves \eqref{hypcone}.

\label{lemmaparametrix}
Let $b\in C^\infty_c(\mathbb{C}\setminus\mathbb{R})$. For $s\in\mathbb{C}$ and $X\in\mathbb{R}^2$ consider the system
\begin{equation}
\label{system}
m=1+s\,\mathcal{C}(bP_0\,n),\qquad n=1+s\,\overline{\mathcal{C}}\big(\overline b\,P_0^{-1}m\big).
\end{equation}
There is an open set $\mathcal U\subset\mathbb{C}$ containing $\mathbb{R}$, which depends on $b$ only through $\|\mathcal{I}|b|\|_\infty$, such that the following holds.
\begin{enumerate}
\item {\em (Solvability).} For $s\in\mathcal U$ and $X\in\mathbb{R}^2$, the system \eqref{system} has a unique solution $(m_s,n_s)\in C_b(\mathbb{C})^2$. For real $s$, $n_s=\overline{m_s}$, and $m_s$ is the solution of $m=1+\mathcal{C}(sbP_0\overline m)$.
\item {\em (Analyticity).} The function
$$W_s(X):=s\int_\mathbb{C} b\,P_0\,n_s\,dA$$
is smooth in $X$, and $\partial^\gamma_XW_s(X)$ is holomorphic in $s\in\mathcal U$ for every $X$ and every multi-index $\gamma$.
\item {\em (Decay).} For every compact set $\mathcal U'\subset\mathcal U$ and every multi-index $\gamma$,
\begin{equation}
\label{decayW}
|\partial^\gamma_XW_s(X)|\lesssim|s|\,\langle X\rangle^{-1-\min(1,|\gamma|)},\qquad s\in\mathcal U',\ X\in\mathbb{R}^2,
\end{equation}
where the constant depends only on $\mathcal U'$, $\gamma$, the support of $b$ and finitely many derivatives of $b$.
\end{enumerate}

\label{propcompact}
Let $a\in C^\infty_c(\mathbb{C}\setminus\mathbb{R})$ be real, and let $m$ and $u$ be given by \eqref{eqm} and \eqref{reconstruction}.
\begin{enumerate}
\item {\em (Regularity and decay).} $u\in C^\infty(\mathbb{R}\times\mathbb{R}^2)$ is real-valued, and $\sup_{|t|\le T}|\partial^\gamma_Xu(t,X)|\lesssim\langle X\rangle^{-2}$ for every multi-index $\gamma$ and $T>0$, with a constant depending on $\gamma$ and $T$.
\item {\em (Equation).} $u$ solves \eqref{kp}, $\|u(t)\|_{L^2}=\|u(0)\|_{L^2}$ for every $t$, and $u\in C^1(\mathbb{R};L^2(\mathbb{R}^2))$ satisfies the Duhamel formula
\begin{equation}
\label{duhamel}
u(t)=S(t)u(0)-6\int_0^tS(t-t')\big(u\partial_xu\big)(t')\,dt',\qquad t\in\mathbb{R} .
\end{equation}
\item {\em (Heat equation).} For every $k\in\mathbb{C}$ and $(t,X)$, $m$ solves
\begin{equation}
\label{heatm}
\partial_ym-\partial_x^2m-2k\partial_xm-u\,m=0 .
\end{equation}
\item {\em (Analyticity in the amplitude).} For $s\in\mathbb{R}$, let $u_s$ be the function reconstructed from $sa$. Then $s\mapsto u_s(0)$ is real-analytic from $\mathbb{R}$ into $L^2(\mathbb{R}^2)$, and for every multi-index $\gamma$,
\begin{equation}
\label{smallcritical}
\|\partial^\gamma_Xu_s(0)\|_{\dot H^{-\frac12,0}}\lesssim_\gamma|s|,\qquad |s|\le1 .
\end{equation}
\end{enumerate}

If $a=0$, then $m=1$ and $u_s=0$ for every $s\in\mathbb{R}$, so all assertions are immediate. We assume $a\neq0$ below.

{\bf Step 1:} Smoothness and decay. Let $W(t,X):=\int aP\overline m\,dA$, so that $u=-\frac2\pi\partial_xW$, and let $w:=-\frac2\pi\partial_yW$. Since $P(k;t,X)=P_0(k;X)e^{it\omega(\zeta(k))}$, Lemma \ref{lemmaparametrix} (i) and (iii) with $b:=ae^{it\omega\circ\zeta}$ and $s=1$ give $|\partial^\gamma_XW(t,X)|\lesssim\langle X\rangle^{-1-\min(1,|\gamma|)}$, uniformly for $|t|\le T$: indeed $|b|=|a|$, so that the set $\mathcal U$ does not depend on $t$, and the derivatives of $b$ are bounded uniformly in $|t|\le T$. Differentiating \eqref{eqm} in $t$ as well, $m$ and $W$ are smooth in $(t,X)$, with bounded derivatives. Hence $u$ and $w$ are smooth and all their derivatives in $X$ are $O(\langle X\rangle^{-2})$, locally uniformly in $t$. The integrands of $W$ and of $\partial_yW$ are invariant under $g\mapsto g^*$, as in Steps 1 and 3 of the proof of Lemma \ref{lemmainverse}, so that $u$ and $w$ are real.\\

\noindent{\bf Step 2:} Expansion at infinity. Let $R_a:=\max\{|k'|:\ k'\in\operatorname{supp} a\}$. For $|k|>R_a$, expanding $\frac1{k-k'}=\sum_{j\ge1}k'^{j-1}k^{-j}$ in \eqref{eqm} gives the convergent expansion
\begin{equation}
\label{expansionm}
m(k)=1+\sum_{j\ge1}\frac{m^{(j)}}{k^j},\qquad m^{(j)}:=\frac1\pi\int_\mathbb{C} k'^{j-1}a(k')P(k')\overline{m(k')}\,dA(k'),
\end{equation}
which may be differentiated term by term in $(t,X)$. In particular $m^{(1)}=\frac W\pi$, so that
\begin{equation}
\label{uwm1}
u=-2\partial_xm^{(1)},\qquad w=-2\partial_ym^{(1)} .
\end{equation}

\noindent{\bf Step 3:} Gauge covariance. Let $E(k):=e^{kx+k^2y-4k^3t}$. Then $\overline{E}/E=e^{-2i\operatorname{Im}(kx+k^2y-4k^3t)}=P$, so that the eigenfunction $\psi:=Em$ of the heat operator satisfies $\bar\partial\psi=E\,aP\overline m=a\overline\psi$. Let $\mathcal L$ be a linear differential operator in $(t,x,y)$ whose coefficients are real and independent of $k$. Since $\mathcal L$ commutes with $\bar\partial_k$ and with complex conjugation, and $a$ does not depend on $(t,X)$, we get $\bar\partial(\mathcal L\psi)=a\overline{\mathcal L\psi}$. Hence $g:=E^{-1}\mathcal L(Em)$ satisfies
\begin{equation}
\label{gauge}
\bar\partial g=E^{-1}a\,\overline{Eg}=aP\overline g .
\end{equation}
We apply this to the heat operator $\partial_y-\partial_x^2-u$ and to the operator $\partial_t+4\partial_x^3+6u\partial_x+3\partial_xu+3w$, which form the Lax pair of KP-II, and whose conjugates by $E$ are
$$\begin{gathered}L_k:=\partial_y-\partial_x^2-2k\partial_x-u,\\ A_k:=\partial_t+4\partial_x^3+12k\partial_x^2+12k^2\partial_x+6u\partial_x+6ku+3\partial_xu+3w .\end{gathered}$$

\noindent{\bf Step 4:} The Lax equations. The function $k\mapsto L_km$ is continuous and, by \eqref{expansionm}, for $|k|>R_a$,
$$L_km=\big(-2\partial_xm^{(1)}-u\big)+\frac1k\big(\partial_ym^{(1)}-\partial_x^2m^{(1)}-2\partial_xm^{(2)}-um^{(1)}\big)+O(k^{-2}).$$
The constant term vanishes by \eqref{uwm1}, so that $L_km\in C_0(\mathbb{C})$. By \eqref{gauge} and the uniqueness part of Lemma \ref{lemmavekua} (i) with $f=0$, $L_km=0$; this is \eqref{heatm}. In particular the coefficient of $k^{-1}$ vanishes:
\begin{equation}
\label{coeffL}
2\partial_xm^{(2)}=\partial_ym^{(1)}-\partial_x^2m^{(1)}-um^{(1)} .
\end{equation}
Similarly, $A_km=k\big(12\partial_xm^{(1)}+6u\big)+\big(12\partial_xm^{(2)}+12\partial_x^2m^{(1)}+6um^{(1)}+3\partial_xu+3w\big)+O(k^{-1})$. The coefficient of $k$ vanishes by \eqref{uwm1}, and by \eqref{coeffL} and \eqref{uwm1} the constant coefficient equals
$$\begin{aligned}&6\partial_ym^{(1)}-6\partial_x^2m^{(1)}-6um^{(1)}+12\partial_x^2m^{(1)}+6um^{(1)}+3\partial_xu+3w\\&\qquad=6\partial_ym^{(1)}+6\partial_x^2m^{(1)}+3\partial_xu+3w=0 .\end{aligned}$$
Hence $A_km\in C_0(\mathbb{C})$, and $A_km=0$ as before.\\

\noindent{\bf Step 5:} The KP-II equation. A direct computation gives
$$\begin{aligned}{}[L_k,A_k]&=-6(\partial_xw-\partial_yu)\partial_x-3\partial_x(\partial_xw-\partial_yu)-6k(\partial_xw-\partial_yu)\\&\quad+\big(\partial_tu+\partial_x^3u+6u\partial_xu+3\partial_yw\big).\end{aligned}$$
By \eqref{uwm1}, $\partial_xw-\partial_yu=-2\partial_x\partial_ym^{(1)}+2\partial_y\partial_xm^{(1)}=0$. Step 4 gives $0=[L_k,A_k]m=(\partial_tu+\partial_x^3u+6u\partial_xu+3\partial_yw)m$, and by \eqref{boundeigen}, $|m(k)-1|\le\frac12$ for $|k|$ large. Hence $\partial_tu+\partial_x^3u+6u\partial_xu+3\partial_yw=0$. Finally, $u$ and $w$ belong to $L^2$, and \eqref{uwm1} gives $\xi\hat w=\eta\hat u$, so that $\hat w=\frac\eta\xi\hat u$ almost everywhere and $\partial_yw=\partial_x^{-1}\partial_y^2u$: $u$ solves \eqref{kp}.\\

\noindent{\bf Step 6:} Conservation of mass. All derivatives of $u$ and $w$ are $O(\langle X\rangle^{-2})$, so that the following integrations by parts are legitimate:
$$\begin{aligned}\frac{d}{dt}\int u^2\,dX&=-2\int u\big(\partial_x^3u+6u\partial_xu+3\partial_yw\big)dX\\&=6\int(\partial_yu)\,w\,dX=6\int(\partial_xw)\,w\,dX=0 .\end{aligned}$$
Moreover, $\partial_tu=-\partial_x^3u-6u\partial_xu-3\partial_yw$ is $O(\langle X\rangle^{-2})$ locally uniformly in $t$, so that, by dominated convergence, $u\in C^1(\mathbb{R};L^2)$. In Fourier variables, $\partial_t\hat u=i\omega\hat u-6\widehat{u\partial_xu}$ almost everywhere, since $\hat w=\frac\eta\xi\hat u$; integrating $\partial_t(e^{-it\omega}\hat u)=-6e^{-it\omega}\widehat{u\partial_xu}$ in time gives \eqref{duhamel}. Steps 1--6 prove (i), (ii) and (iii).\\

\noindent{\bf Step 7:} Proof of (iv). Apply Lemma \ref{lemmaparametrix} with $b:=a$. By (i), for real $s$, $W_s$ is the function $W(0,\cdot)$ associated with the coefficient $sa$, so that $u_s(0)=-\frac2\pi\partial_xW_s$. By (ii) and (iii), for every $X$, $s\mapsto\partial_xW_s(X)$ is holomorphic on $\mathcal U$, and it is bounded by $C\langle X\rangle^{-2}\in L^2$ uniformly on compact subsets of $\mathcal U$. By the Cauchy integral formula and dominated convergence, $s\mapsto\partial_xW_s$ is holomorphic from $\mathcal U$ into $L^2(\mathbb{R}^2)$, hence real-analytic on $\mathbb{R}$. For \eqref{smallcritical}, let $G:=\partial^\gamma_XW_s$. By the Cauchy--Schwarz inequality in $\xi$, for every $y$,
$$\big\||D_x|^{\frac12}G(\cdot,y)\big\|_{L^2(\mathbb{R})}^2\le\|G(\cdot,y)\|_{L^2(\mathbb{R})}\|\partial_xG(\cdot,y)\|_{L^2(\mathbb{R})},$$
where $|D_x|^{\frac12}$ denotes the Fourier multiplier with symbol $|\xi|^{\frac12}$ in the variable $x$. By \eqref{decayW}, $\|G(\cdot,y)\|_{L^2(\mathbb{R})}\lesssim|s|\langle y\rangle^{-\frac12}$ and $\|\partial_xG(\cdot,y)\|_{L^2(\mathbb{R})}\lesssim|s|\langle y\rangle^{-\frac32}$. Integrating in $y$,
$$\|\partial^\gamma_Xu_s(0)\|_{\dot H^{-\frac12,0}}^2=\frac4{\pi^2}\int_\mathbb{R}\big\||D_x|^{\frac12}G(\cdot,y)\big\|_{L^2(\mathbb{R})}^2dy\lesssim s^2\int_\mathbb{R}\langle y\rangle^{-2}dy .$$

\label{propplancherel}
Let $a\in C^\infty_c(\mathbb{C}\setminus\mathbb{R})$ be real, and let $u$ be given by \eqref{reconstruction}. Then
\begin{equation}
\label{plancherelcompact}
\|u(0)\|_{L^2}^2=8\int_\mathbb{C}|k_2||a|^2\,dA=\|\mathcal{B} a\|_{L^2}^2 .
\end{equation}

\label{proprapid}
Let $a$ satisfy \eqref{hypa} and let $u$ be given by \eqref{reconstruction}. Then:
\begin{enumerate}
\item $u\in C(\mathbb{R};L^2(\mathbb{R}^2))$, $u$ and $\partial_xu$ are bounded on $\mathbb{R}\times\mathbb{R}^2$, $u$ satisfies the Duhamel formula \eqref{duhamel}, and $\|u(t)\|_{L^2}=\|u(0)\|_{L^2}$ for every $t\in\mathbb{R}$;
\item $\|u(0)\|_{L^2}^2=8\int_\mathbb{C}|k_2||a|^2dA=\|\mathcal{B} a\|_{L^2}^2$.
\end{enumerate}

{\bf Step 1:} Compactly supported approximation. For $R\ge1$ let $\vartheta_R(k):=\vartheta(k/R)\big(1-\vartheta(4Rk_2)\big)$, where $\vartheta$ is the cutoff fixed in the Notations. Then $\vartheta_R\in C^\infty_c(\mathbb{C}\setminus\mathbb{R})$ is real-valued, $\vartheta_R(\bar k)=\vartheta_R(k)$, $0\le\vartheta_R\le1$, $\vartheta_R=1$ on $\{|k|\le R,\ |k_2|\ge R^{-1}\}$, and $\operatorname{supp}\vartheta_R\subset\{|k|\le2R,\ |k_2|\ge(4R)^{-1}\}$. Let
$$a_R:=\vartheta_R\,(\varrho_{\varepsilon_R}\ast a),$$
where $\varepsilon_R\le(8R)^{-1}$ is so small that $|\varrho_{\varepsilon_R}\ast a-a|\le R^{-1}$ on $\operatorname{supp}\vartheta_R$; this is possible since $a$ is uniformly continuous on the compact set $\{|k|\le3R,\ |k_2|\ge(8R)^{-1}\}$. Since $\varrho$ is radial and $a(\bar k)=\overline{a(k)}$, the coefficient $a_R\in C^\infty_c(\mathbb{C}\setminus\mathbb{R})$ is real. If $|k'-k|\le\varepsilon_R$ and $|k|\le2R$, then $|\zeta(k')-\zeta(k)|\lesssim\langle k\rangle\varepsilon_R\lesssim1$, so that $\langle \zeta(k')\rangle\sim\langle \zeta(k)\rangle$; hence \eqref{hypa} gives
\begin{equation}
\label{uniformaR}
|a_R(k)|\lesssim\langle \zeta(k)\rangle^{-6}\qquad\mbox{uniformly in}\ R,
\end{equation}
and $a_R\to a$ uniformly on the compact subsets of $\mathbb{C}\setminus\mathbb{R}$. By Lemma \ref{lemmacauchy} (v), applied with the majorants $C\langle \zeta\rangle^{-6}$ and $C|k_2|\langle \zeta\rangle^{-6}$ of Lemma \ref{lemmaweights} (ii),
$$\|\mathcal{I}|a_R-a|\|_\infty+\|\mathcal{I}(|k_2||a_R-a|)\|_\infty\longrightarrow0\qquad(R\to\infty).$$
Let $m_R$ and $u_R$ be the eigenfunction and the reconstructed function of $a_R$. By \eqref{comparison}, $m_R\to m$ in $C_b(\mathbb{C})$, uniformly in $(t,X)$. Subtracting the equations \eqref{eqmx} of $a_R$ and of $a$,
$$\begin{aligned}\partial_xm_R-\partial_xm&=\mathcal{C}\big(a_RP\overline{(\partial_xm_R-\partial_xm)}\big)+\mathcal{C}\big((a_R-a)P\overline{\partial_xm}\big)\\&\quad+\mathcal{C}\big(-2ik_2(a_RP\overline{m_R}-aP\overline m)\big),\end{aligned}$$
and the last two terms tend to zero in $C_b$, uniformly in $(t,X)$, by the convergences above; Lemma \ref{lemmavekua} (iii) gives $\partial_xm_R\to\partial_xm$, and in the same way $\partial_x^2m_R\to\partial_x^2m$, uniformly in $(k;t,X)$. By \eqref{uniformaR} and the proof of Lemma \ref{lemmainverse}, the bounds $|\partial_xm_R|+|\partial_x^2m_R|\lesssim\langle k\rangle^{-1}$ hold uniformly in $R$, so that the integrands of $u_R$ and $\partial_xu_R$ have the integrable majorant $C(|k_2|+k_2^2+\langle k\rangle^{-1})\langle \zeta\rangle^{-6}$. By dominated convergence, $u_R\to u$ and $\partial_xu_R\to\partial_xu$ pointwise on $\mathbb{R}\times\mathbb{R}^2$, with $\sup_R(\|u_R\|_\infty+\|\partial_xu_R\|_\infty)<\infty$. Propositions \ref{propcompact} and \ref{propplancherel}, Fatou's lemma and the dominated convergence theorem (with \eqref{uniformaR}) give, for every $t$,
\begin{equation}
\label{fatou}
\begin{aligned}\|u(t)\|_{L^2}^2\le\liminf_{R\to\infty}\|u_R(t)\|_{L^2}^2&=\lim_{R\to\infty}8\int_\mathbb{C}|k_2||a_R|^2\,dA\\&=8\int_\mathbb{C}|k_2||a|^2\,dA=\|\mathcal{B} a\|_{L^2}^2 .\end{aligned}
\end{equation}

\noindent{\bf Step 2:} The Duhamel formula. By Proposition \ref{propcompact}, each $u_R$ is a smooth solution of $\partial_x(\partial_tu_R+\partial_x^3u_R+3\partial_x(u_R^2))+3\partial_y^2u_R=0$. By Step 1 we can pass to the limit in the sense of distributions on $\mathbb{R}\times\mathbb{R}^2$:
\begin{equation}
\label{kpdistrib}
\partial_x\big(\partial_tu+\partial_x^3u+3\partial_x(u^2)\big)+3\partial_y^2u=0 .
\end{equation}
Since $u$ and $\partial_xu$ are bounded by Lemma \ref{lemmainverse} (iii), and $\|u(t)\|_{L^2}\le\|\mathcal{B} a\|_{L^2}$ by \eqref{fatou}, the function $6u\partial_xu$ belongs to $L^\infty(\mathbb{R};L^2)$, and
$$\tilde u(t):=S(t)u(0)-6\int_0^tS(t-t')\big(u\partial_xu\big)(t')\,dt'$$
belongs to $C(\mathbb{R};L^2)$ and satisfies $\partial_x(\partial_t\tilde u+\partial_x^3\tilde u+6u\partial_xu)+3\partial_y^2\tilde u=0$ in the sense of distributions, while $u$ satisfies the same equation by \eqref{kpdistrib}, since $6u\partial_xu=3\partial_x(u^2)$. The difference $z:=u-\tilde u$ is bounded in $L^2$ and satisfies $\partial_x(\partial_tz+\partial_x^3z)+3\partial_y^2z=0$. Moreover $z$ is weakly continuous in $L^2$, with $z(0)=0$: $\tilde u$ is continuous, and $u(t')\to u(t)$ pointwise and boundedly in $L^2$ as $t'\to t$, by Lemma \ref{lemmainverse} (iii) and \eqref{fatou}. In Fourier variables, the equation reads $\partial_t\hat z=i\omega\hat z$ in $\mathcal D'(\mathbb{R}\times\{\xi\neq0\})$, so that $\partial_t(e^{-it\omega}\hat z)=0$ there, and for every test function $\varphi$ supported in $\{\xi\neq0\}$, the continuous function $t\mapsto\int e^{-it\omega}\hat z(t)\overline{\varphi}\,d\xi\,d\eta$ is constant, hence equal to its value $0$ at $t=0$. Since $\{\xi=0\}$ is a null set, $z=0$: $u=\tilde u\in C(\mathbb{R};L^2)$ satisfies \eqref{duhamel}. Then $S(-t)u(t)=u(0)-6\int_0^tS(-t')(u\partial_xu)(t')\,dt'$ is absolutely continuous in $L^2$, and for almost every $t$
$$\frac d{dt}\|u(t)\|_{L^2}^2=-12\big(u,u\partial_xu\big)=-12\int_{\mathbb{R}^2}u^2\partial_xu\,dX=-4\int_{\mathbb{R}^2}\partial_x(u^3)\,dX=0,$$
since $u^3$ and $\partial_x(u^3)=3u^2\partial_xu$ are integrable. This proves (i). Note that we did not need $u(t)$ to belong to the domain of the singular operator $\partial_x^{-1}\partial_y^2$.\\

\noindent{\bf Step 3:} Proof of (ii). By \eqref{hypa} with $q=6$, the coefficient $a$ satisfies \eqref{hypF1} with $F:=C\langle \zeta\rangle^{-6}$, and $F$ satisfies the conditions \eqref{weightsF} by Lemma \ref{lemmaweights} (ii). Proposition \ref{propcone} and Lemma \ref{lemmaweak}, together with the conservation of mass, give $S(-t)u(t)\rightharpoonup\mathcal{B} a$ as $t\to\pm\infty$. By weak lower semicontinuity, $\|\mathcal{B} a\|_{L^2}\le\liminf\|S(-t)u(t)\|_{L^2}=\|u(0)\|_{L^2}$, and \eqref{fatou} at $t=0$ gives the reverse inequality. Hence $\|u(0)\|_{L^2}=\|\mathcal{B} a\|_{L^2}$, which, together with \eqref{bornisometry}, proves (ii).

\label{lemmagreen}
Let $k=k_1+ik_2\in\mathbb{C}$ and $X=(x,y)$ with $y\neq0$.
\begin{enumerate}
\item {\em (Formula).} With $\tilde x=x+2k_1y$, $E_y:=\{|s|>|k_2|\}$ if $y>0$ and $E_y:=\{|s|<|k_2|\}$ if $y<0$, let
\begin{equation}
\label{formulagreen}
G_k(x,y):=\frac{\operatorname{sgn}(y)}{2\pi}\,e^{-ik_2\tilde x}\int_{E_y}e^{is\tilde x}\,w(s)\,ds,\qquad w(s):=e^{-(s^2-k_2^2)y}.
\end{equation}
Then $G_k$ is continuous on $\mathbb{R}^2\setminus\{0\}$, and it is a fundamental solution: $(\partial_y-\partial_x^2-2k\partial_x)G_k=\delta_0$ in $\mathcal D'(\mathbb{R}^2)$. For real $k=k_1$, $G_{k_1}(x,y)=\1_{\{y>0\}}(4\pi y)^{-\frac12}e^{-(x+2k_1y)^2/(4y)}$ is a causal heat kernel.
\item {\em (Size).}
\begin{equation}
\label{sizegreen}
|G_k(x,y)|\lesssim\min\big(|\tilde x|^{-1},\,|y|^{-\frac12},\,(|k_2||y|)^{-1}\big)\lesssim\frac1{|x+2k_1y|+|y|^{\frac12}} .
\end{equation}
\item {\em (Spectral regularity).} $k\mapsto G_k(X)$ is continuous on $\mathbb{C}$ and smooth on $\mathbb{C}\setminus\mathbb{R}$, with $|\nabla_kG_k(X)|\lesssim1$ for $k\notin\mathbb{R}$. In particular $|G_k(X)-G_{k'}(X)|\lesssim|k-k'|$ for all $k,k'\in\mathbb{C}$.
\item {\em (Symmetries).} $\overline{G_k}=G_{\bar k}$ and $G_k(X)e^{-iX\cdot\zeta(k)}=G_{\bar k}(X)$.
\item {\em ($\bar\partial$-derivative).} For $k\notin\mathbb{R}$, $\bar\partial_kG_k(X)=-\frac{i\operatorname{sgn}(k_2)}{2\pi}e^{iX\cdot\zeta(k)}$.
\end{enumerate}

{\bf Step 1:} Proof of (i). The formula comes from \eqref{defgreen} as follows: we replace $\eta$ by $\eta+2k_1\xi$, which turns $x\xi+y\eta$ into $\tilde x\xi+y\eta$ and the symbol into $(\xi+k_2)^2-k_2^2+i\eta$; for a real number $c\neq0$, $\frac1{2\pi}\int_\mathbb{R}\frac{e^{iy\eta}}{c+i\eta}d\eta$ equals $\1_{\{y>0\}}e^{-cy}$ if $c>0$ and $-\1_{\{y<0\}}e^{-cy}$ if $c<0$; with $c=s^2-k_2^2$ and $\xi=s-k_2$ this gives \eqref{formulagreen}. To prove that $G_k$ is a fundamental solution, note that each function $f_s(x,y):=e^{i(s-k_2)\tilde x-(s^2-k_2^2)y}$ satisfies $(\partial_y-\partial_x^2-2k\partial_x)f_s=0$, since
$$\begin{aligned}&2ik_1(s-k_2)-(s^2-k_2^2)+(s-k_2)^2-2ik(s-k_2)\\&\qquad=(s-k_2)\big(2ik_1-(s+k_2)+(s-k_2)-2ik_1+2k_2\big)=0,\end{aligned}$$
and that the integrals in \eqref{formulagreen} may be differentiated under the integral sign for $y\neq0$. Hence $(\partial_y-\partial_x^2-2k\partial_x)G_k=0$ on $\{y\neq0\}$. For $k_2=0$ the Gaussian integral gives the heat kernel. As $y\to0^\pm$ with $x\neq0$, both expressions in \eqref{formulagreen} tend to $-\frac{e^{-ik_2x}}{2\pi}\frac{2\sin(|k_2|x)}x$: for $y\to0^+$ we write $\int_{\{|s|>|k_2|\}}=\int_\mathbb{R}-\int_{\{|s|<|k_2|\}}$, and the Gaussian integral over $\mathbb{R}$ tends to zero. Hence $G_k$ is continuous on $\mathbb{R}^2\setminus\{0\}$. In $\mathcal D'(\mathbb{R}_x)$, the same decomposition shows that $G_k(\cdot,y)$ tends to $\frac{e^{-ik_2x}}{2\pi}\big(2\pi\delta_0-\int_{\{|s|<|k_2|\}}e^{isx}ds\big)$ as $y\to0^+$, and to $-\frac{e^{-ik_2x}}{2\pi}\int_{\{|s|<|k_2|\}}e^{isx}ds$ as $y\to0^-$. Since the operator is of first order in $y$, an integration by parts in $y$ on each half-plane shows that $(\partial_y-\partial_x^2-2k\partial_x)G_k$ equals the jump $G_k(\cdot,0^+)-G_k(\cdot,0^-)=\delta_0(x)$ times $\delta_0(y)$, that is, $\delta_0$.\\

\noindent{\bf Step 2:} Proof of (ii). Let $\mu:=|k_2|$. For $y>0$, $w$ decreases from $1$ to $0$ on each half-line of $E_y$; for $y<0$, $w$ is monotone on $[-\mu,0]$ and on $[0,\mu]$, with values in $[0,1]$. One integration by parts in $s$ gives $\big|\int_{E_y}e^{is\tilde x}w\,ds\big|\le\frac4{|\tilde x|}$. For $y>0$, writing $s=\pm(\mu+r)$ and using $s^2-\mu^2\ge r^2+2\mu r$, the integral is bounded by $2\int_0^\infty e^{-r^2y}dr\lesssim y^{-\frac12}$ and by $2\int_0^\infty e^{-2\mu ry}dr=(\mu y)^{-1}$. For $y<0$, $\mu^2-s^2\ge\mu(\mu-|s|)$ gives the bound $2\int_0^\mu e^{-\mu(\mu-s)|y|}ds\le\min\big(2\mu,\,2(\mu|y|)^{-1}\big)$, which is at most $2|y|^{-\frac12}$ and at most $2(\mu|y|)^{-1}$. This proves \eqref{sizegreen}.\\

\noindent{\bf Step 3:} Proof of (iii). Continuity at $k_2=0$ follows from \eqref{formulagreen} by dominated convergence. Since $G_k(x,y)$ is a function of $(\tilde x,y,k_2)$, we have $\partial_{k_1}G_k=2y\,\partial_{\tilde x}G_k$, and by \eqref{formulagreen}
\begin{equation}
\label{dk1green}
y\,\partial_{\tilde x}G_k=-ik_2y\,G_k+\frac{\operatorname{sgn}(y)}{2\pi}e^{-ik_2\tilde x}\,iy\int_{E_y}s\,e^{is\tilde x}w(s)\,ds .
\end{equation}
The first term is bounded by \eqref{sizegreen}, and $|y|\int_{E_y}|s|w(s)\,ds\le1$ in both cases, by the explicit primitive of $sw(s)$. For $k_2>0$, differentiating the prefactor, the weight and the endpoints $\pm k_2$ of $E_y$ in \eqref{formulagreen} gives, for both signs of $y$,
\begin{equation}
\label{dk2green}
\partial_{k_2}G_k=(-i\tilde x+2k_2y)\,G_k-\frac1{2\pi}\big(1+e^{-2ik_2\tilde x}\big),
\end{equation}
which is bounded by \eqref{sizegreen}; the case $k_2<0$ follows from (iv) below. The Lipschitz bound follows, since $G_k(X)$ is continuous across the real axis.\\

\noindent{\bf Step 4:} Proof of (iv) and (v). The integral in \eqref{formulagreen} is real, since $E_y$ and $w$ are even in $s$, and it depends on $k_2$ only through $|k_2|$. Hence $\overline{G_k}=G_{\bar k}$ and $G_ke^{2ik_2\tilde x}=G_{\bar k}$, with $2k_2\tilde x=-X\cdot\zeta(k)$. For (v), let $k_2>0$. By \eqref{dk1green} and \eqref{dk2green},
$$\begin{aligned}\bar\partial_kG_k&=y\,\partial_{\tilde x}G_k+\frac i2\partial_{k_2}G_k\\&=\frac{\tilde x}2G_k+\frac{\operatorname{sgn}(y)}{2\pi}e^{-ik_2\tilde x}\,iy\int_{E_y}s\,e^{is\tilde x}w\,ds-\frac i{4\pi}\big(1+e^{-2ik_2\tilde x}\big).\end{aligned}$$
Since $\partial_sw=-2syw$, we have $iys\,w=-\frac i2\partial_sw$, and an integration by parts, with $w(\pm k_2)=1$, gives
$$iy\int_{E_y}s\,e^{is\tilde x}w\,ds=-\frac i2\,\operatorname{sgn}(y)\big(e^{-ik_2\tilde x}-e^{ik_2\tilde x}\big)-\frac{\tilde x}2\int_{E_y}e^{is\tilde x}w\,ds .$$
The last term cancels with $\frac{\tilde x}2G_k$, and we obtain $\bar\partial_kG_k=-\frac i{4\pi}\big(e^{-2ik_2\tilde x}-1\big)-\frac i{4\pi}\big(1+e^{-2ik_2\tilde x}\big)=-\frac i{2\pi}e^{-2ik_2\tilde x}=-\frac i{2\pi}e^{iX\cdot\zeta(k)}$. The case $k_2<0$ follows from (iv), since $\bar\partial_k\big(\overline{G_{\bar k}}\big)=\overline{(\bar\partial G)(\bar k)}$ and $\zeta(\bar k)=-\zeta(k)$.

\label{lemmagreenop}
\begin{enumerate}
\item For $f\in\mathcal{K}$, $H\in L^\infty$ and $k,k'\in\mathbb{C}$,
$$\begin{gathered}\|G_k\ast(fH)\|_{L^\infty}\lesssim\|f\|_\mathcal{K}\|H\|_{L^\infty},\\ \|(G_k-G_{k'})\ast(fH)\|_{L^\infty}\lesssim|k-k'|\,\|f\|_{L^1}\|H\|_{L^\infty}.\end{gathered}$$
\item {\em (High energy).} If $f\in\mathcal{K}_0$, then $\sup_{|k|\ge R}\|G_k\ast(f\,\cdot\,)\|_{L^\infty\to L^\infty}\to0$ as $R\to\infty$, uniformly for $f$ in a convergent sequence of $\mathcal{K}_0$.
\item {\em (Uniform invertibility).} Let $u_0\in\mathcal{K}_0\cap L^1$. There is $R_0\ge1$ such that every $k$ in
$$\Omega:=\{|k|>R_0\}\cup\{|k_2|<R_0^{-1}\}$$
is a regular point, and $\sup_{k\in\Omega}\|T_k^{-1}\|_{L^\infty\to L^\infty}<\infty$. If $u_{0,n}\to u_0$ in $\mathcal{K}\cap L^1$, the same holds for $u_{0,n}$, with the same $R_0$ and bound, for $n$ large.
\item {\em (Pointwise continuity).} Let $u_0\in L^1\cap L^\infty$ and let $k$ be a regular point. If $H_j\to H$ pointwise with $\sup_j\|H_j\|_{L^\infty}<\infty$, then $T_k^{-1}H_j\to T_k^{-1}H$ pointwise.
\end{enumerate}

\label{lemmaembedding}
\begin{enumerate}
\item Let $1<p,q<\infty$ with $\frac1p+\frac2q<2$. Then $\|f\|_\mathcal{K}\lesssim_{p,q}\|f\|_{L^1}+\|f\|_{L^q_yL^p_x}$, and $L^1\cap L^q_yL^p_x\subset\mathcal{K}_0$. In particular $L^1\cap L^2\subset\mathcal{K}_0$.
\item If $\hat f$ is supported in $\{|\xi|\le2^{j+1},\ |\eta|\le2^{l+1}\}$ for some $j,l\ge0$, then, for $1<p,q<\infty$ with $\frac1p+\frac2q<2$,
\begin{equation}
\label{bernsteinK}
\|f\|_\mathcal{K}\lesssim_{p,q}2^{(1-\frac1p)j+(1-\frac1q)l}\|f\|_{L^1},\qquad \|f\|_\mathcal{K}\lesssim2^{\frac l2}\|f\|_{L^1}.
\end{equation}
\end{enumerate}

\label{propdirect}
Let $u_0$ satisfy \eqref{expdecay}, and let $\chi$ and $a$ be given by \eqref{defchi}, \eqref{defa} and Theorem \ref{thmgrin}. Then:
\begin{enumerate}
\item $a$ satisfies \eqref{hypa};
\item for every $X\in\mathbb{R}^2$, $\chi(\cdot;X)=m(\cdot;0,X)$, where $m$ is the solution of \eqref{eqm} at $t=0$; in particular $\chi$ is bounded on $(\mathbb{C}\setminus\mathbb{R})\times\mathbb{R}^2$, and the formula \eqref{defa} holds at every $k\in\mathbb{C}\setminus\mathbb{R}$;
\item the function reconstructed from $a$ by \eqref{reconstruction} at $t=0$ is $u_0$.
\end{enumerate}

{\bf Step 1:} Derivatives in $X$. Let $\mathcal R$ be the set of regular points. Let $k\in\mathcal R$. Since convolution commutes with translations, $\tau_h\chi_k=1+G_k\ast((\tau_hu_0)\,\tau_h\chi_k)$ for $h\in\mathbb{R}^2$, hence
\begin{equation}
\label{translationchi}
T_k(\tau_h\chi_k-\chi_k)=G_k\ast\big((\tau_hu_0-u_0)\,\tau_h\chi_k\big).
\end{equation}
The difference quotients of $u_0$ converge to its derivatives in $L^1\cap L^2$, hence in $\mathcal{K}$ by Lemma \ref{lemmaembedding} (i). By \eqref{translationchi} and Lemma \ref{lemmagreenop} (i), $\chi_k$ is differentiable in $X$ in the $L^\infty$ norm, and by induction on $|\gamma|$,
\begin{equation}
\label{derivativeschi}
T_k\partial^\gamma\chi_k=\sum_{0<\nu\le\gamma}\binom\gamma\nu\,G_k\ast\big((\partial^\nu u_0)\,\partial^{\gamma-\nu}\chi_k\big),\qquad \gamma\neq0 .
\end{equation}
Hence every derivative of $\chi_k$ is bounded, uniformly for $k\in\Omega$ and locally uniformly on $\mathcal R$, and $\chi_k$ is smooth. Since $\chi_k-1=T_k^{-1}(G_k\ast u_0)$, Lemma \ref{lemmagreenop} (ii) and \eqref{derivativeschi} also give
\begin{equation}
\label{chiinfinity}
\lim_{|k|\to\infty}\Big(\|\chi_k-1\|_{L^\infty}+\sum_{0<|\gamma|\le2}\|\partial^\gamma\chi_k\|_{L^\infty}\Big)=0 .
\end{equation}

\noindent{\bf Step 2:} Derivatives in $k$ and the $\bar\partial$ equation. Let $k\in\mathcal R\setminus\mathbb{R}$, $e\in\{1,i\}$ and $h\in\mathbb{R}\setminus\{0\}$ small. Subtracting the equations \eqref{eqchi} at $k+he$ and at $k$,
$$T_k\frac{\chi_{k+he}-\chi_k}h=\frac{G_{k+he}-G_k}h\ast\big(u_0\chi_{k+he}\big).$$
By Lemma \ref{lemmagreen} (iii) and Lemma \ref{lemmagreenop} (i), $\|\chi_{k+he}-\chi_k\|_{L^\infty}\lesssim|h|$, and the kernels on the right-hand side are bounded and converge pointwise on $\{y\neq0\}$ to $\partial_eG_k$. By dominated convergence, the right-hand side converges pointwise and boundedly to $(\partial_eG_k)\ast(u_0\chi_k)$, and Lemma \ref{lemmagreenop} (iv) shows that $\chi(\cdot;X)$ is differentiable in the direction $e$ at $k$, for every $X$, with
\begin{equation}
\label{dkchi}
T_k\,\partial_e\chi_k=(\partial_eG_k)\ast(u_0\chi_k),\qquad \|\partial_e\chi_k\|_{L^\infty}\lesssim\|T_k^{-1}\|^2\,\|u_0\|_{L^1},
\end{equation}
where we used $\|\chi_k\|_{L^\infty}\le\|T_k^{-1}\|$. Arguing as in Step 1, where now the derivatives in $X$ of $(\partial_eG_k)\ast(u_0\chi_k)$ fall on the smooth integrable function $u_0\chi_k$, we see that all derivatives in $X$ of $\partial_e\chi_k$ are bounded, locally uniformly on $\mathcal R\setminus\mathbb{R}$ and uniformly on $\Omega\setminus\mathbb{R}$. Next, combining \eqref{dkchi} with Lemma \ref{lemmagreen} (v), and using $(X-X')\cdot\zeta(k)=X\cdot\zeta(k)-X'\cdot\zeta(k)$,
$$\begin{aligned}T_k\,\bar\partial\chi_k&=(\bar\partial G_k)\ast(u_0\chi_k)\\&=-\frac{i\operatorname{sgn}(k_2)}{2\pi}e^{iX\cdot\zeta(k)}\int_{\mathbb{R}^2}u_0(X')\chi_k(X')e^{-iX'\cdot\zeta(k)}\,dX'=a(k)\,e^{iX\cdot\zeta(k)} .\end{aligned}$$
On the other hand, conjugating \eqref{eqchi} and using $\overline{G_k}=G_{\bar k}$ and $G_{\bar k}(X-X')=G_k(X-X')e^{-i(X-X')\cdot\zeta(k)}$ (Lemma \ref{lemmagreen} (iv)), we find that $\bar k$ is a regular point, $\overline{\chi_k}=\chi_{\bar k}$, and $T_k\big(e^{iX\cdot\zeta(k)}\overline{\chi_k}\big)=e^{iX\cdot\zeta(k)}$. Since $T_k$ is invertible, we obtain, for $k\in\mathcal R\setminus\mathbb{R}$,
\begin{equation}
\label{dbarchi}
\bar\partial_k\chi(k;X)=a(k)\,e^{iX\cdot\zeta(k)}\,\overline{\chi(k;X)},\qquad \chi(\bar k;X)=\overline{\chi(k;X)} .
\end{equation}
Finally, on the strip $\{|k_2|<R_0^{-1}\}$, which is contained in $\Omega$, the same subtraction gives $\|\chi_k-\chi_{k'}\|_{L^\infty}\lesssim|k-k'|$, across the real axis.\\

\noindent{\bf Step 3:} Decay of $a$ on $\Omega$. Let $k\in\Omega\setminus\mathbb{R}$. Since $(1-\partial_x^2-\partial_y^2)e^{-iX\cdot\zeta(k)}=\langle \zeta(k)\rangle^2e^{-iX\cdot\zeta(k)}$, integrations by parts in \eqref{defa}, legitimate by \eqref{expdecay} and Step 1, give for every integer $q\ge0$
$$\langle \zeta(k)\rangle^{2q}a(k)=-\frac{i\operatorname{sgn}(k_2)}{2\pi}\int_{\mathbb{R}^2}(1-\partial_x^2-\partial_y^2)^q\big(u_0\chi_k\big)\,e^{-iX\cdot\zeta(k)}\,dX,$$
hence $|a(k)|\lesssim_q\langle \zeta(k)\rangle^{-2q}$.
By Step 2 we may differentiate \eqref{defa} under the integral sign:
\begin{equation}
\label{dka}
\partial_ea(k)=-\frac{i\operatorname{sgn}(k_2)}{2\pi}\int_{\mathbb{R}^2}\Big(u_0\,\partial_e\chi_k-i\big(X\cdot\partial_e\zeta(k)\big)u_0\chi_k\Big)e^{-iX\cdot\zeta(k)}\,dX,
\end{equation}
with $|\partial_e\zeta(k)|\le4\langle k\rangle$. The functions $u_0\partial_e\chi_k$, $xu_0\chi_k$ and $yu_0\chi_k$ have integrable derivatives of all orders, uniformly on $\Omega\setminus\mathbb{R}$, and the same integrations by parts give $|\nabla_ka(k)|\lesssim_q\langle k\rangle\langle \zeta(k)\rangle^{-2q}$. By the Lipschitz bound at the end of Step 2, the integral in \eqref{defa} is continuous across the real axis, so that $a$ has continuous extensions to $\overline{\mathbb{C}^+}$ and to $\overline{\mathbb{C}^-}$. By \eqref{dbarchi}, $\zeta(\bar k)=-\zeta(k)$ and the reality of $u_0$, $a(\bar k)=\overline{a(k)}$ for $k\in\mathcal R\setminus\mathbb{R}$.\\

\noindent{\bf Step 4:} Proof of (i). By Theorem \ref{thmgrin}, $a$ is $C^1$ on $\mathbb{C}\setminus\mathbb{R}$, hence bounded with bounded derivatives on the compact set $\{|k|\le R_0,\ |k_2|\ge R_0^{-1}\}$, on which $\langle \zeta(k)\rangle$ is bounded; by density, $a(\bar k)=\overline{a(k)}$ on $\mathbb{C}\setminus\mathbb{R}$. Together with Step 3, this proves \eqref{hypa}.\\

\noindent{\bf Step 5:} Proof of (ii). Fix $X$. By Theorem \ref{thmgrin}, both sides of \eqref{dbarchi} are continuous on $\mathbb{C}\setminus\mathbb{R}$, and they coincide on the dense set $\mathcal R\setminus\mathbb{R}$ (Lemma \ref{lemmairregular}); hence \eqref{dbarchi} holds on $\mathbb{C}\setminus\mathbb{R}$. On the strip $\{|k_2|<R_0^{-1}\}$, the function $k\mapsto\chi(k;X)$ is Lipschitz by Step 2, so that its distributional derivative $\bar\partial\chi$ is a bounded function, with no singular part on the real axis. Hence
$$\bar\partial\chi(\cdot;X)=a\,P\,\overline{\chi(\cdot;X)}\quad\mbox{in}\ \mathcal D'(\mathbb{C}),\qquad P=e^{iX\cdot\zeta(k)}=e^{i\phi(k;0,X)} .$$
The function $g:=\chi(\cdot;X)-1$ is continuous on $\mathbb{C}$, tends to zero at infinity by \eqref{chiinfinity}, and satisfies $\bar\partial g=aP\overline g+aP$. By (i), Lemma \ref{lemmaweights} (ii) and Lemma \ref{lemmacauchy} (iv), $\mathcal{I}|a|\in C_0(\mathbb{C})$, and the uniqueness part of Lemma \ref{lemmavekua} (i), with the coefficient $aP$ and $f=aP$, shows that $g=m(\cdot;0,X)-1$. By Lemma \ref{lemmainverse} (i), $|\chi(k;X)|\le1+\|\mathcal{I}|a|\|_\infty e^{2\|\mathcal{I}|a|\|_\infty}$ for all $(k,X)$. Finally, let $k\in\mathbb{C}\setminus\mathbb{R}$ and let $k_j\in\mathcal R\setminus\mathbb{R}$ tend to $k$. Then $a(k_j)\to a(k)$ and $\chi(k_j;X)\to\chi(k;X)$ for every $X$, and the dominated convergence theorem, with the majorant $C|u_0|$, shows that the formula \eqref{defa} holds at $k$.\\

\noindent{\bf Step 6:} Proof of (iii). By (ii), $\partial_xm(k;0,X)=\partial_x\chi(k;X)$ for $k\in\Omega\setminus\mathbb{R}$. By Lemma \ref{lemmainverse} (ii), $\partial_xm=\mathcal{C} f$ with $f:=\partial_x(aP\overline m)=aP\big(-2ik_2\overline m+\overline{\partial_xm}\big)$. Since $|k_2|\langle k\rangle\le|k_2|+|k_1k_2|+k_2^2\lesssim\langle \zeta(k)\rangle^2$, \eqref{hypa} and Lemma \ref{lemmainverse} (i), (ii) give $|f|\lesssim\langle k\rangle^{-1}\langle \zeta\rangle^{-6}$. Hence $f\in L^1(\mathbb{C})$ by \eqref{weightsE}, and
$$k\,\mathcal{C} f(k)-\frac1\pi\int_\mathbb{C} f\,dA=\frac1\pi\int_\mathbb{C} f(k')\frac{k'}{k-k'}\,dA(k').$$
On $\{|k'|\le\frac{|k|}2\}$ the integrand is bounded by $|f(k')|$ and tends to zero as $|k|\to\infty$. On $\{|k'|>\frac{|k|}2\}$ we use $|k'||f(k')|\lesssim\langle \zeta(k')\rangle^{-6}$, so that, for $|k|\ge2$, this part is bounded by $C\mathcal{I}(\langle \zeta\rangle^{-6}\1_{\{|k'|>|k|/2\}})(k)\lesssim\frac{1+\log|k|}{|k|}$ by \eqref{weightstail}. Hence $k\,\partial_xm(k;0,X)\to\frac1\pi\int_\mathbb{C} f\,dA$ as $|k|\to\infty$. On the other hand, \eqref{eqchi} gives $2k\partial_x\chi=\partial_y\chi-\partial_x^2\chi-u_0\chi$, which tends to $-u_0$ uniformly by \eqref{chiinfinity}. Therefore $u_0=-\frac2\pi\int_\mathbb{C}\partial_x(aP\overline m)\,dA$, which is \eqref{reconstruction} at $t=0$.

\label{corsmooth}
Let $u_0$ satisfy \eqref{expdecay}, let $a$ be its scattering coefficient, and let $u$ be the solution of \eqref{kp}. Then $u$ coincides with the function reconstructed from $a$ by \eqref{reconstruction}, and
\begin{equation}
\label{plancherelsmooth}
\|u_0\|_{L^2}^2=8\int_\mathbb{C}|k_2||a(k)|^2\,dA(k)=\|\mathcal{B} a\|_{L^2}^2 .
\end{equation}

\label{lemmadifferences}
Let $u_0$ satisfy \eqref{expdecay}, let $k\in\mathbb{C}\setminus\mathbb{R}$ be a regular point of $u_0$ with $\|T_k^{-1}\|\le\Lambda$, and let $g\in L^\infty(\mathbb{R}^2)$ solve
\begin{equation}
\label{eqg}
g=G_k\ast(u_0g)+G_k\ast f_1+(\partial_eG_k)\ast f_2
\end{equation}
for some $e\in\{1,i\}$, $f_1\in\mathcal{K}$ and $f_2\in L^1(\mathbb{R}^2)$. Then, for all $h,h'\in\mathbb{R}^2$, with implicit constants which depend only on $\Lambda$,
\begin{enumerate}
\item $\|\delta_hg\|_{L^\infty}\lesssim\|\delta_hu_0\|_\mathcal{K}\|g\|_{L^\infty}+\|\delta_hf_1\|_\mathcal{K}+\|\delta_hf_2\|_{L^1}$;
\item for the second-order differences,
\begin{multline*}
\|\delta_{h'}\delta_hg\|_{L^\infty}\lesssim\|\delta_{h'}\delta_hu_0\|_\mathcal{K}\|g\|_{L^\infty}+\|\delta_hu_0\|_\mathcal{K}\|\delta_{h'}g\|_{L^\infty}+\|\delta_{h'}u_0\|_\mathcal{K}\|\delta_hg\|_{L^\infty}\\
+\|\delta_{h'}\delta_hf_1\|_\mathcal{K}+\|\delta_{h'}\delta_hf_2\|_{L^1};
\end{multline*}
\item {\em (Equations).} for $\partial\in\{\partial_x,\partial_y\}$ and $e\in\{1,i\}$, the functions $g=\chi_k-1$, $\partial\chi_k$, $\partial_e\chi_k$ and $\partial\partial_e\chi_k$ are bounded and solve \eqref{eqg}, with $(f_1,f_2)$ equal to $(u_0,0)$, $\big((\partial u_0)\chi_k,0\big)$, $(0,u_0\chi_k)$ and $\big((\partial u_0)\partial_e\chi_k,\partial(u_0\chi_k)\big)$ respectively.
\end{enumerate}

\label{lemmabootstrap}
Let $u_{0,n}\in C^\infty_c(\mathbb{R}^2)$, $n\ge1$, be real with $\sup_n(\|u_{0,n}\|_{L^1}+\|u_{0,n}\|_{L^2})<\infty$, and let $a_n$ and $m_n$ be their scattering coefficients and the corresponding eigenfunctions \eqref{eqm}. Assume that there are a compact set $K\subset\mathbb{C}\setminus\mathbb{R}$ and a measurable function $F\ge0$ on $\mathbb{C}$ with $\|\mathcal{I} F\|_\infty<\infty$ such that $|a_n|\le F$ on $(\mathbb{C}\setminus\mathbb{R})\setminus K$ for every $n$.
\begin{enumerate}
\item {\em (Uniform bounds).} $\sup_n\big(\|a_n\|_\infty+\|\mathcal{I}|a_n|\|_\infty\big)<\infty$.
\end{enumerate}
Assume moreover that, for some $\theta\in(0,1]$,
\begin{equation}
\label{tightmoment}
\sup_n\|\langle X\rangle^\theta u_{0,n}\|_{L^1}<\infty,\qquad \lim_{R\to\infty}\sup_n\|\langle X\rangle^\theta u_{0,n}\|_{L^1(\{|X|>R\})}=0,
\end{equation}
and let $K'\subset\mathbb{C}\setminus\mathbb{R}$ be compact.
\begin{enumerate}[resume]
\item {\em (H\"older regularity).} If $\theta<1$, then
\begin{equation}
\label{littleholder}
\lim_{r\to0}\ \sup_n\ \sup_{k,k+h\in K',\ 0<|h|\le r}\frac{|a_n(k+h)-a_n(k)|}{|h|^\theta}=0 .
\end{equation}
\item {\em (Lipschitz regularity).} If $\theta=1$, then $\sup_n\sup_{K'}|\nabla_ka_n|<\infty$.
\end{enumerate}

{\bf Step 1:} Proof of (i). Let $M_n:=\|\mathcal{I}|a_n|\|_\infty$, which is finite for each $n$, as well as $\|a_n\|_\infty$, by \eqref{hypa}, Lemma \ref{lemmaweights} (ii) and Lemma \ref{lemmacauchy} (iv). By \eqref{plancherelsmooth}, $\int|k_2||a_n|^2dA=\frac18\|u_{0,n}\|_{L^2}^2\lesssim1$, and since $|k_2|$ is bounded below on $K$, $\|a_n\|_{L^2(K)}+\|a_n\|_{L^1(K)}\lesssim1$. Let $R_K\ge1$ be such that $K\subset D(0,R_K)$, and $r:=(1+\|a_n\|_\infty)^{-1}$. For $|k|\le2R_K$ we split the potential of $|a_n|\1_K$ at distance $r$ from $k$, and we use the Cauchy--Schwarz inequality on the annulus $\{r\le|k-k'|\le3R_K\}$:
$$\begin{aligned}\mathcal{I}(|a_n|\1_K)(k)&\le2r\|a_n\|_\infty+\frac1\pi\|a_n\|_{L^2(K)}\Big(\int_{\{r\le|z|\le3R_K\}}\frac{dA(z)}{|z|^2}\Big)^{\frac12}\\&\le C+C\sqrt{\log(2+\|a_n\|_\infty)} .\end{aligned}$$
For $|k|>2R_K$ the potential is bounded by $C\|a_n\|_{L^1(K)}$, and outside $K$ we use $\mathcal{I} F\le C$. Hence
\begin{equation}
\label{boot1}
M_n\le C\Big(1+\sqrt{\log(2+\|a_n\|_\infty)}\Big) .
\end{equation}
On the other hand, by Proposition \ref{propdirect} (ii), the formula \eqref{defa} holds at every $k\in\mathbb{C}\setminus\mathbb{R}$ with $\chi=m_n(\cdot;0,\cdot)$, and \eqref{boundeigen} gives
\begin{equation}
\label{boot2}
\|a_n\|_\infty\le\frac{\|u_{0,n}\|_{L^1}}{2\pi}\sup_{k,X}|m_n(k;0,X)|\le C\big(1+M_ne^{2M_n}\big).
\end{equation}
Since $M_n\le e^{M_n}$, we deduce from \eqref{boot2} that $2+\|a_n\|_\infty\le Ce^{3M_n}$, so that $\sqrt{\log(2+\|a_n\|_\infty)}\le C+\sqrt{3M_n}$, and then \eqref{boot1} gives $M_n\le C(1+\sqrt{M_n})$. Since $M_n<\infty$, this implies $M_n\le C$ for all $n$, and then $\sup_n\|a_n\|_\infty<\infty$ by \eqref{boot2}.\\

\noindent{\bf Step 2:} Proof of (ii). By (i) and \eqref{boundeigen}, $\sup_{n,k,X}|m_n(k;0,X)|<\infty$, and the source $a_nP\overline{m_n}$ of the equation $m_n-1=\mathcal{C}(a_nP\overline{m_n})$ satisfies $\|a_nP\overline{m_n}\|_\infty+\|\mathcal{I}|a_nP\overline{m_n}|\|_\infty\lesssim1$. By \eqref{cauchymodulus}, for every $\theta'\in(0,1)$,
\begin{equation}
\label{holdermn}
|m_n(k+h;0,X)-m_n(k;0,X)|\lesssim_{\theta'}|h|^{\theta'},\qquad k\in\mathbb{C},\ |h|\le1,
\end{equation}
uniformly in $n$ and $X$; for $\frac12<|h|\le1$ this follows from the boundedness of $m_n$. Let $K'\subset\mathbb{C}\setminus\mathbb{R}$ be compact, and let $k,k+h\in K'$ with $0<|h|<\min(1,\operatorname{dist}(K',\mathbb{R}))$, so that $k$ and $k+h$ belong to the same half-plane. By \eqref{defa} and Proposition \ref{propdirect} (ii), and since $|\zeta(k+h)-\zeta(k)|\lesssim_{K'}|h|$,
$$\begin{aligned}|a_n(k+h)-a_n(k)|&\lesssim\int_{\mathbb{R}^2}|u_{0,n}|\,|m_n(k+h;0,X)-m_n(k;0,X)|\,dX\\&\quad+\int_{\mathbb{R}^2}|u_{0,n}|\min\big(1,|X||h|\big)\,dX .\end{aligned}$$
We choose $\theta'\in(\theta,1)$ in \eqref{holdermn}, and for $R\ge1$ we split the last integral at $|X|=R$, using $\min(1,s)\le s^\theta$ on $\{|X|>R\}$:
$$\frac{|a_n(k+h)-a_n(k)|}{|h|^\theta}\lesssim|h|^{\theta'-\theta}+R|h|^{1-\theta}+\sup_n\int_{\{|X|>R\}}\langle X\rangle^\theta|u_{0,n}|\,dX .$$
By \eqref{tightmoment}, choosing first $R$ large and then $|h|$ small proves \eqref{littleholder}.\\

\noindent{\bf Step 3:} Proof of (iii). Fix $\theta'\in(0,1)$, let $d:=\frac14\operatorname{dist}(K',\mathbb{R})$, and let $K_1$ and $K_2$ be the sets of points at distance at most $d$, respectively $3d$, from $K'$; they are compact subsets of $\{|k_2|\ge d\}$. The computation of Step 2 with $\theta=1$ gives $|a_n(k+h)-a_n(k)|\lesssim|h|^{\theta'}$ for $k,k+h\in K_2$ in the same half-plane with $|h|\le1$, while two points of $K_2$ in different half-planes are at distance at least $2d$. Since moreover $|P(k;0,X)-P(k';0,X)|\le\min(2,|X||\zeta(k)-\zeta(k')|)$, \eqref{holdermn} shows that $f_n:=a_nP\overline{m_n}$ satisfies $\|f_n\|_{C^{\theta'}(K_2)}\lesssim\langle X\rangle^{\theta'}$, uniformly in $n$. Let $k_0\in K_1$ and $\vartheta_{k_0}:=\vartheta(\frac{\cdot-k_0}d)$, which equals $1$ on $D(k_0,d)$ and is supported in $D(k_0,2d)\subset K_2$. Then $\|\vartheta_{k_0}f_n\|_{C^{\theta'}}\lesssim\langle X\rangle^{\theta'}$. Since $\bar\partial m_n=f_n$, the function $m_n-\mathcal{C}(\vartheta_{k_0}f_n)$ is holomorphic on $D(k_0,d)$, and it is bounded by $C$ there, so that its gradient at $k_0$ is $O(d^{-1})$. Moreover $\mathcal{C} g=4\partial_k\mathcal Ng$, where $\mathcal Ng:=\frac1{2\pi}\int_\mathbb{C}\log|\cdot-k'|\,g(k')\,dA(k')$ is the Newtonian potential of $g$ \cite[Lemma 4.1]{GilbargTrudinger}. Since $\vartheta_{k_0}f_n$ is supported in $D(k_0,2d)$, \cite[Lemma 4.4]{GilbargTrudinger}, applied with the discs $D(k_0,d)\subset D(k_0,2d)$, bounds the second derivatives of $\mathcal N(\vartheta_{k_0}f_n)$ on $D(k_0,d)$ by $C\|\vartheta_{k_0}f_n\|_{C^{\theta'}}$; the pairs of points at distance larger than $1$, which are not seen by our H\"older norm, contribute at most $2\sup|\vartheta_{k_0}f_n|$. Hence $\mathcal{C}(\vartheta_{k_0}f_n)$ is $C^1$ near $k_0$, with $|\nabla\mathcal{C}(\vartheta_{k_0}f_n)(k_0)|\lesssim\langle X\rangle^{\theta'}$. Thus $m_n(\cdot;0,X)$ is $C^1$ on the interior of $K_1$, which is a neighborhood of $K'$, and $|\nabla_km_n(k_0;0,X)|\lesssim\langle X\rangle^{\theta'}$ for $k_0\in K_1$, uniformly in $n$. Differentiating \eqref{defa} under the integral sign, with the majorant $C\langle X\rangle|u_{0,n}|$, we obtain for $k\in K'$
$$|\nabla_ka_n(k)|\lesssim\int_{\mathbb{R}^2}|u_{0,n}|\big(|\nabla_km_n(k;0,X)|+\langle k\rangle|X|\big)\,dX\lesssim\int_{\mathbb{R}^2}\langle X\rangle|u_{0,n}|\,dX\lesssim1 .$$

\label{lemmaapprox}
Let $0<\theta\le1$, and let $u_0\in L^2(\mathbb{R}^2)$ be real with $\langle X\rangle^\theta u_0\in L^1(\mathbb{R}^2)$. There are $\varepsilon_n\in(0,\frac1n]$ such that the real functions
\begin{equation}
\label{defu0n}
u_{0,n}:=\varrho_{\varepsilon_n}\ast\big(\vartheta(\cdot/n)\,u_0\big)\in C^\infty_c(\mathbb{R}^2),\qquad n\ge1,
\end{equation}
where $\vartheta$ and $\varrho_\varepsilon$ are the cutoff and the mollifier of the Notations, satisfy the following.
\begin{enumerate}
\item {\em (Convergence).} $u_{0,n}\to u_0$ in $L^1\cap L^2$, and $\langle X\rangle^\theta u_{0,n}\to\langle X\rangle^\theta u_0$ in $L^1$; in particular, \eqref{tightmoment} holds.
\item {\em (Weights).} For $|Z|\le1$, the function $\mu_Z(X):=\langle X\rangle^\theta\langle X-Z\rangle^{-\theta}$ satisfies $\|\mu_Z\|_{W^{3,\infty}}\lesssim1$, and
\begin{equation}
\label{weightconv}
\langle X\rangle^\theta u_{0,n}=\int_{\mathbb{R}^2}\varrho_{\varepsilon_n}(Z)\,\mu_Z\,\tau_{-Z}\big(\vartheta(\cdot/n)\langle X\rangle^\theta u_0\big)\,dZ .
\end{equation}
\end{enumerate}

\label{lemmamixednorm}
Let $0<\alpha<2$, $0<\beta<1$ and $Y\in\{L^1(\mathbb{R}^2),\mathcal{K},L^\infty(\mathbb{R}^2)\}$.
\begin{enumerate}
\item {\em (Littlewood--Paley pieces).} If $Y\neq L^\infty$, then $\|f\|_{\alpha,\beta;Y}\lesssim N_{\alpha,\beta}(f;Y)$.
\item {\em (Products).} $\|fg\|_{\alpha,\beta;Y}\lesssim\|f\|_{\alpha,\beta;Y}\|g\|_{\alpha,\beta;L^\infty}$, and $\|c\|_{\alpha,\beta;L^\infty}\lesssim\|c\|_{W^{3,\infty}}$ for every $c\in W^{3,\infty}(\mathbb{R}^2)$.
\item {\em (Fourier decay).} $|\hat\Phi(\xi,\eta)|\lesssim\|\Phi\|_{\alpha,\beta;L^1}\langle \xi\rangle^{-\alpha}\langle \eta\rangle^{-\beta}$ for $(\xi,\eta)\in\mathbb{R}^2$.
\item {\em (Eigenfunctions).} Let $u_0$ satisfy \eqref{expdecay}, and let $k\in\mathbb{C}\setminus\mathbb{R}$ be a regular point of $u_0$ with $\|T_k^{-1}\|\le\Lambda$. Then, for $e\in\{1,i\}$, $\|\chi_k\|_{\alpha,\beta;L^\infty}+\|\partial_e\chi_k\|_{\alpha,\beta;L^\infty}$ is bounded by a constant which depends only on $\Lambda$ and on an upper bound for $\|u_0\|_{\alpha,\beta;\mathcal{K}}+\|u_0\|_{\alpha,\beta;L^1}$.
\end{enumerate}

\label{lemmamixed}
Let $0<\alpha<2$ and $0<\beta<1$ with $\alpha+2\beta>2$. Let $u_{0,n}\in C^\infty_c(\mathbb{R}^2)$ be real functions such that
\begin{enumerate}
\item $u_{0,n}\to u_0$ in $L^1\cap L^2$;
\item the first moments of $u_{0,n}$ are tight, that is, \eqref{tightmoment} holds with $\theta=1$;
\item $\sup_n\big(\|u_{0,n}\|_{\alpha,\beta;\mathcal{K}}+\|u_{0,n}\|_{\alpha,\beta;L^1}+\|xu_{0,n}\|_{\alpha,\beta;L^1}+\|yu_{0,n}\|_{\alpha,\beta;L^1}\big)<\infty$.
\end{enumerate}
Then the scattering coefficients $a_n$ of $u_{0,n}$ satisfy, uniformly in $n$ and $k\in\mathbb{C}\setminus\mathbb{R}$,
\begin{equation}
\label{envelopemixed}
|a_n(k)|\lesssim F_{\alpha,\beta}(k),\qquad |\nabla_ka_n(k)|\lesssim\langle k\rangle\,F_{\alpha,\beta}(k),
\end{equation}
and a subsequence of $(a_n)$ converges uniformly on the compact subsets of $\mathbb{C}\setminus\mathbb{R}$.

\label{lemmasandwich}
Let $u_{0,n}\in C^\infty_c(\mathbb{R}^2)$ be real with $u_{0,n}\to u_0$ in $L^1\cap L^2$, and let $a_n$ be their scattering coefficients. Assume that there is $F\in L^\infty(\mathbb{C})$ with $\mathcal{I} F\in C_0(\mathbb{C})$ such that $|a_n|\le F$ for all $n$, and that $a_n\to a$ uniformly on the compact subsets of $\mathbb{C}\setminus\mathbb{R}$. Then
\begin{equation}
\label{conclusionsandwich}
\lim_{n\to\infty}\|\mathcal{B} a_n-\mathcal{B} a\|_{L^2}=0,\qquad \|\mathcal{B} a\|_{L^2}=\|u_0\|_{L^2}.
\end{equation}

\label{propcritical}
Let $(a_n)_{n\ge1}$ be a family of coefficients which satisfy \eqref{hypa}, let $u_n$ be the functions reconstructed from $a_n$ by \eqref{reconstruction}, and $g_n:=\mathcal{B} a_n$. Assume that there are $C_*>0$, $\delta_*\in(0,1]$ and nondecreasing functions $d_j:(0,\delta_*]\to[0,\infty)$, $j\ge0$, with
\begin{equation}
\label{hypshell1}
\lim_{\delta\to0}\sum_{j\ge0}d_j(\delta)=0,
\end{equation}
such that, for all $n\ge1$ and $k,k'\in\mathbb{C}\setminus\mathbb{R}$,
\begin{equation}
\label{hypshell2}
|a_n(k)|\le C_*\langle \zeta(k)\rangle^{-\frac32},\qquad |a_n(k')-a_n(k)|\le\delta^{\frac12}\,2^{-\frac{3j}2}\,d_j(\delta),
\end{equation}
where the second bound is required whenever $k\in A_j$, $k_2k'_2>0$ and $0<\delta:=|k'-k|\langle k\rangle\le\delta_*$.
Then \eqref{hypcone} holds for every compact set $V\subset\mathcal{V}$.

\label{lemmashell}
\begin{enumerate}
\item For $k_0\in\mathbb{C}$ and $0<r_1\le r\le1$, with $E:=\{r_1\le|k-k_0|\le r\}$,
\begin{equation}
\label{annulusbound}
\sup_{k\in\mathbb{C}}\mathcal{I}\big(|\cdot-k_0|^{-1}\1_E\big)(k)\lesssim\log\frac{2r}{r_1},\qquad \sup_{k\in\mathbb{C}}\mathcal{I}\big(|\cdot-k_0|^{-2}\1_E\big)(k)\lesssim\frac1{r_1} .
\end{equation}
\item For every $j\ge0$,
\begin{equation}
\label{shellbound}
\int_{A_j}(1+|k_2|)W_t\,dA+\sup_{k\in\mathbb{C}}\mathcal{I}\big((1+|k_2|)W_t\1_{A_j}\big)(k)\lesssim2^{\frac{3j}2}.
\end{equation}
\item For $0<\varepsilon\le\frac12$,
\begin{equation}
\label{stripbound}
\sup_{k\in\mathbb{C}}\mathcal{I}\big(\langle \zeta\rangle^{-\frac32}\1_{\{|k_2|<\varepsilon\}}\big)(k)+\sup_{k\in\mathbb{C}}\mathcal{I}\big(\langle \cdot\rangle^{-2}\1_{\{|k_2|<\varepsilon\}}\big)(k)\lesssim\varepsilon\log\frac2\varepsilon .
\end{equation}
\end{enumerate}

\label{lemmaregular}
There are $t_0\ge1$ and $C>0$ such that $\sigma_t\le1$ for $|t|\ge t_0$, and such that, for $|t|\ge t_0$, $X/t\in V$ and $n\ge1$, the following holds.
\begin{enumerate}
\item {\em (Smoothness and size).} The restrictions of $a_{n,t}$ to $\mathbb{C}^+$ and to $\mathbb{C}^-$ extend to smooth functions on $\mathbb{C}$, and $|a_{n,t}(k)|\le C\langle \zeta(k)\rangle^{-\frac32}$ for $k\in\mathbb{C}\setminus\mathbb{R}$, as well as for the two traces $a^\pm_{n,t}$ on $\mathbb{R}$.
\item {\em (Errors).} The functions
\begin{equation}
\label{errordensities}
\mathcal E_{n,t}:=(1+|k_2|)\,|a_n-a_{n,t}|,\qquad \mathcal E'_{n,t}:=(1+|k_2|)\,(1-\vartheta_t)\,\frac{|\nabla_ka_{n,t}|}{|\partial_k\phi|},
\end{equation}
defined on $\mathbb{C}\setminus\mathbb{R}$, where $\mathcal E'_{n,t}:=0$ on $D(k_+,\rho)\cup D(k_-,\rho)$, satisfy
\begin{equation}
\label{errorbounds}
\|\mathcal E_{n,t}\|_{L^1}+\|\mathcal{I}\mathcal E_{n,t}\|_\infty+\|\mathcal E'_{n,t}\|_{L^1}+\|\mathcal{I}\mathcal E'_{n,t}\|_\infty\le C|t|^{-\frac12}\sigma_t .
\end{equation}
\item {\em (Decay for fixed $n$).} For every $n$ and $k\in\mathbb{C}\setminus\mathbb{R}$, $|a_{n,t}(k)|+\langle k\rangle^{-1}|\nabla_ka_{n,t}(k)|\lesssim_n\langle \zeta(k)\rangle^{-6}$.
\end{enumerate}

We choose $t_0$ such that $C_\ell\rho\le\min(\delta_*,\frac1{16})$, $4\rho<r_0$ and $\sigma_t\le1$ for $|t|\ge t_0$. We treat $k\in\overline{\mathbb{C}^+}$; the case of $\overline{\mathbb{C}^-}$ is identical. Let $\tilde a_n:=a_n^+\circ\Pi_+$, which is bounded and continuous on $\mathbb{C}$.\\

\noindent{\bf Step 1:} Proof of (i). The right-hand side of \eqref{defant}, with $\Pi_+$ and $a_n^+$, is defined for every $k\in\mathbb{C}$, and it is a smooth function of $k$, since $\ell_t$ is smooth and positive and $\tilde a_n$ is bounded and continuous. Moreover $\int\varrho_{\ell_t(k)}(k-k')\,dA(k')=1$ for every $k$, so that $\int\nabla_k\big(\varrho_{\ell_t(k)}(k-k')\big)\,dA(k')=0$, and a direct computation using $|\nabla\ell_t|\le C_\ell$ gives $\int|\nabla_k(\varrho_{\ell_t(k)}(k-k'))|\,dA(k')\lesssim\ell_t(k)^{-1}$. Let $k'\in D(k,\ell_t(k))$. Then $|\Pi_+(k')-k|\le\ell_t(k)$, and $\delta':=|\Pi_+(k')-k|\langle k\rangle\le\ell_t(k)\langle k\rangle\le C_\ell\rho$ by \eqref{propellt}. In particular $|\zeta(\Pi_+(k'))-\zeta(k)|\le8\delta'\le\frac12$, so that $\langle \zeta(\Pi_+(k'))\rangle\ge\langle \zeta(k)\rangle-\frac12\ge\frac12\langle \zeta(k)\rangle$, and \eqref{hypshell2}, together with the continuity of $a_n^+$, gives $|\tilde a_n(k')|\le2^{\frac32}F(k)$. Integrating against $\varrho_{\ell_t(k)}(k-k')$ proves (i).\\

\noindent{\bf Step 2:} Proof of (ii). Let $j\ge0$ and $k\in A_j\cap\mathbb{C}^+$. If $k'\in D(k,\ell_t(k))$ and $\Pi_+(k')\notin\mathbb{R}\cup\{k\}$, which holds for almost every $k'$, then \eqref{hypshell2}, the monotonicity of $d_j$ and the identity $(\ell_t(k)\langle k\rangle)^{\frac12}=|t|^{-\frac12}W_t(k)$ give
\begin{equation}
\label{regmodulus}
|\tilde a_n(k')-a_n(k)|\le|t|^{-\frac12}W_t(k)\,2^{-\frac{3j}2}d_j(C_\ell\rho).
\end{equation}
We have $a_n(k)-a_{n,t}(k)=\int\varrho_{\ell_t(k)}(k-k')\big(a_n(k)-\tilde a_n(k')\big)dA(k')$ and
$$\nabla_ka_{n,t}(k)=\int_\mathbb{C}\nabla_k\big(\varrho_{\ell_t(k)}(k-k')\big)\,\big(\tilde a_n(k')-a_n(k)\big)\,dA(k'),$$
so that \eqref{regmodulus} and Step 1 give
\begin{equation}
\label{regerror}
|a_n(k)-a_{n,t}(k)|+\ell_t(k)|\nabla_ka_{n,t}(k)|\lesssim|t|^{-\frac12}W_t(k)\,2^{-\frac{3j}2}d_j(C_\ell\rho).
\end{equation}
If $\vartheta_t(k)\neq1$, then $|k-k_\pm|\ge\rho$, and $\ell_t(k)^{-1}\le\frac16|\partial_k\phi(k)|$ by \eqref{propellt}. Hence \eqref{regerror} gives $\mathcal E_{n,t}+\mathcal E'_{n,t}\lesssim|t|^{-\frac12}(1+|k_2|)W_t\,2^{-\frac{3j}2}d_j(C_\ell\rho)$ on $A_j$, and summing the bounds \eqref{shellbound} over $j$ proves (ii).\\

\noindent{\bf Step 3:} Proof of (iii). For fixed $n$, $\tilde a_n$ is locally Lipschitz, with $|\nabla\tilde a_n|\le|\nabla a_n|\circ\Pi_+$ almost everywhere, and the change of variables $k'=k-\ell_t(k)z$ in \eqref{defant} gives $|\nabla a_{n,t}(k)|\le(1+C_\ell)\sup_{k'\in D(k,\ell_t(k))}|\nabla a_n(\Pi_+(k'))|$. The points $\Pi_+(k')$, $k'\in D(k,\ell_t(k))$, belong to $D(k,\ell_t(k))$, on which $\langle \zeta\rangle$ and $\langle k\rangle$ change by bounded factors, by Step 1. Hence \eqref{hypa} with $q=6$ gives (iii).

\label{lemmaoschalf}
Let $\frac12<\alpha<1$, and let $t_0$ be as above. There is $C>0$ such that, for $|t|\ge t_0$, $X/t\in V$, $n\ge1$, $c_n\in\{a_n,\ k_2a_n\}$ and every function $f$ on $\mathbb{C}$ with $\|f\|_{C^\alpha}<\infty$,
\begin{equation}
\label{oschalf}
\big\|\mathcal{C}\big(c_n\,P\,f\big)\big\|_\infty\le C|t|^{-\frac12}\,\|f\|_{C^\alpha} .
\end{equation}

Fix $V$ and $\alpha\in(\frac12,1)$, and let $|t|\ge t_0$ and $X/t\in V$, with $t_0$ as above.\\

\noindent{\bf Step 1:} Uniform bounds. By \eqref{envelopehalf} and the remarks which follow it, Step 1 of the proof of Proposition \ref{propcone} applies with the majorant $F$, and $\|m_n\|_\infty+\|\partial_xm_n\|_\infty\lesssim1$. The sources $a_nP\overline{m_n}$ and $a_nP\overline{\partial_xm_n}-2ik_2a_nP\overline{m_n}$ of the equations \eqref{eqm} and \eqref{eqmx} are therefore bounded by $CF_1$, which is bounded and has a bounded Riesz potential. By \eqref{cauchymodulus}, and since $|h|\log\frac1{|h|}\lesssim_\alpha|h|^\alpha$ for $|h|\le\frac12$, while the case $\frac12<|h|\le1$ follows from the boundedness of $m_n$ and $\partial_xm_n$,
\begin{equation}
\label{holderm}
\|m_n\|_{C^\alpha}+\|\partial_xm_n\|_{C^\alpha}\lesssim1,
\end{equation}
uniformly in $n$, $t$ and $X$.\\

\noindent{\bf Step 2:} Decay of the eigenfunctions. By \eqref{eqm} and \eqref{eqmx},
$$m_n-1=\mathcal{C}\big(a_nP\overline{m_n}\big),\qquad \partial_xm_n=\mathcal{C}\big(a_nP\overline{\partial_xm_n}\big)-2i\,\mathcal{C}\big(k_2a_nP\overline{m_n}\big).$$
Lemma \ref{lemmaoschalf}, applied with $f\in\{\overline{m_n},\overline{\partial_xm_n}\}$, and \eqref{holderm} give
\begin{equation}
\label{decayhalf}
\|m_n-1\|_\infty+\|\partial_xm_n\|_\infty\lesssim\rho=|t|^{-\frac12}.
\end{equation}
By the definition of $B_n$ in \eqref{remainderfn} and by \eqref{cancellation},
\begin{equation}
\label{boundBhalf}
\begin{gathered}
|B_n|\le2(1+|k_2|)\big(\|m_n-1\|_\infty+\|\partial_xm_n\|_\infty\big)\lesssim(1+|k_2|)\rho,\\
|\partial_kB_n|\le\|m_n-1\|_\infty+|a_n|\|\partial_xm_n\|_\infty\lesssim\rho .
\end{gathered}
\end{equation}

\noindent{\bf Step 3:} The remainder. By \eqref{remainderfn}, the difference $u_n(t,X)-S(t)g_n(X)$ equals $-\frac2\pi\int_\mathbb{C} a_nPB_n\,dA$, and we decompose
$$\begin{aligned}\int_\mathbb{C} a_nPB_n\,dA&=\int_\mathbb{C}(a_n-a_{n,t})PB_n\,dA+\int_\mathbb{C}\vartheta_ta_{n,t}PB_n\,dA\\&\quad+\int_\mathbb{C}(1-\vartheta_t)a_{n,t}PB_n\,dA .\end{aligned}$$
All three integrals converge absolutely for each fixed $n$, by Lemma \ref{lemmaregular} (iii), Lemma \ref{lemmainverse} (i), (ii) and \eqref{weightsE}. By \eqref{boundBhalf} and \eqref{errorbounds}, the first integral is bounded by $C\rho\|\mathcal E_{n,t}\|_{L^1}\lesssim\rho|t|^{-\frac12}\sigma_t=|t|^{-1}\sigma_t$. By Lemma \ref{lemmaregular} (i) and \eqref{boundBhalf}, the second one is bounded by $C\rho\,|D(k_+,2\rho)\cup D(k_-,2\rho)|\lesssim\rho^3$.

In the third integral we integrate by parts in $\mathbb{C}^+$ and in $\mathbb{C}^-$, as in Step 5 of the proof of Proposition \ref{propcone}. With $Q:=(1-\vartheta_t)a_{n,t}B_n$, which is continuous up to the real axis from each side, we obtain
$$\int_\mathbb{C} QP\,dA=-\int_{\mathbb{C}\setminus\mathbb{R}}P\,\partial_k\Big(\frac Q{i\partial_k\phi}\Big)dA-\frac1{2i}\int_\mathbb{R}\frac{Q^+-Q^-}{i\partial_k\phi}\,dk_1,$$
where the radial cutoffs are removed exactly as in that proof, by the decay for fixed $n$. On the real axis, $\vartheta_t=0$, $k_2=0$ and $B_n=\overline{\partial_xm_n}$, so that $|Q^\pm|\lesssim\rho$ by Lemma \ref{lemmaregular} (i) and \eqref{decayhalf}; since $|\partial_k\phi(k_1)|\gtrsim|t|(1+k_1^2)$, the boundary term is $O(\rho|t|^{-1})$. In the bulk term, the derivative falls on $\vartheta_t$, on $a_{n,t}$, on $B_n$ or on $(\partial_k\phi)^{-1}$. The derivative of $\vartheta_t$ is $O(\rho^{-1})$ on $D(k_\pm,2\rho)\setminus D(k_\pm,\rho)$, where $|a_{n,t}B_n|\lesssim\rho$ and $|\partial_k\phi|^{-1}\lesssim\rho$; it contributes $O(\rho^{-1}\cdot\rho\cdot\rho\cdot\rho^2)=O(\rho^3)$. By \eqref{boundBhalf} and \eqref{errorbounds}, the term with the derivative of $a_{n,t}$ is bounded by $C\rho\|\mathcal E'_{n,t}\|_{L^1}\lesssim\rho|t|^{-\frac12}\sigma_t=|t|^{-1}\sigma_t$. By \eqref{boundBhalf}, the derivative of $B_n$ contributes at most $C\rho\int(1-\vartheta_t)\frac{F}{|\partial_k\phi|}dA$, and the integral is $O\big(|t|^{-1}\int_{D_\pm}|k-k_\pm|^{-1}dA+|t|^{-1}\int F\langle k\rangle^{-2}dA\big)=O(|t|^{-1})$. Finally, the derivative of $(\partial_k\phi)^{-1}$ contributes at most $C\rho\int(1-\vartheta_t)\frac{F_1|\partial_k^2\phi|}{|\partial_k\phi|^2}dA$, and the integral is $O\big(|t|^{-1}\int_{D_\pm\setminus D(k_\pm,\rho)}|k-k_\pm|^{-2}dA+|t|^{-1}\int F_1\langle k\rangle^{-3}dA\big)=O(|t|^{-1}\log(2+|t|))$. Here we used the bounds on $\partial_k\phi$ and $\partial_k^2\phi$ of Lemma \ref{lemmaphase} (i) and (ii), and $\int F_1\langle k\rangle^{-1}dA<\infty$.\\

\noindent{\bf Step 4:} Conclusion. Collecting Step 3, and recalling $\rho=|t|^{-\frac12}$, we obtain
$$\sup_{n\ge1}\ \sup_{X/t\in V}\ |u_n(t,X)-S(t)g_n(X)|\lesssim|t|^{-1}\sigma_t+|t|^{-\frac32}\log(2+|t|),$$
and $\sigma_t\to0$ proves \eqref{hypcone}.

\label{lemmahalfdirect}
Let $u_0$ be real with $\langle X\rangle^{\frac12}u_0\in B^2_{1,1}(\mathbb{R}^2)$, and let $u_{0,n}$ be the functions given by Lemma \ref{lemmaapprox} with $\theta=\frac12$. After removal of finitely many indices $n$, the following holds.
\begin{enumerate}
\item The scattering coefficients $a_n$ of $u_{0,n}$ satisfy the assumptions \eqref{hypshell1} and \eqref{hypshell2} of Proposition \ref{propcritical}.
\item A subsequence of $(a_n)$ converges uniformly on the compact subsets of $\mathbb{C}\setminus\mathbb{R}$.
\end{enumerate}

{\bf Step 1:} Approximation. By the remark following Theorem \ref{thmmain}, $u_0\in L^2$, and $\langle X\rangle^{\frac12}u_0\in B^2_{1,1}\subset L^1$, so that Lemma \ref{lemmaapprox} applies. By Lemma \ref{lemmaapprox} (i), $u_{0,n}\to u_0$ in $L^1\cap L^2$, hence in $\mathcal{K}$ by Lemma \ref{lemmaembedding} (i), and \eqref{tightmoment} holds with $\theta=\frac12$.\\

\noindent{\bf Step 2:} Common moduli of smoothness. We claim that
\begin{equation}
\label{sumvarpi}
\begin{gathered}
\sum_{l\ge0}2^{\frac{3l}2}\varpi(2^{-l})<\infty,\\
\|\langle X\rangle^{\frac12}u_0\|_Y+\|\nabla(\langle X\rangle^{\frac12}u_0)\|_Y<\infty\qquad\mbox{for}\ Y\in\{L^1,\mathcal{K}\},
\end{gathered}
\end{equation}
and that, for all $n\ge1$, $h\in\mathbb{R}^2$ and $Y\in\{L^1,\mathcal{K}\}$,
\begin{equation}
\label{moduluscommon}
\begin{gathered}
\|\delta_h^2u_{0,n}\|_Y+\|\delta_h^2(\langle X\rangle^{\frac12}u_{0,n})\|_{L^1}\lesssim\varpi(|h|),\\
\|u_{0,n}\|_Y+\|\nabla u_{0,n}\|_Y+\|\langle X\rangle^{\frac12}u_{0,n}\|_{L^1}+\|\nabla(\langle X\rangle^{\frac12}u_{0,n})\|_{L^1}\lesssim1 .
\end{gathered}
\end{equation}
Let $f\in B^2_{1,1}$. For $m\ge0$, the block $\Delta_mf$ is the convolution of itself with $\tilde\kappa_m:=2^{2m}\tilde\kappa(2^m\cdot)$, where $\tilde\kappa$ is a Schwartz function on $\mathbb{R}^2$ such that $\tilde\kappa\ast g=g$ whenever $\hat g$ is supported in $\{|(\xi,\eta)|\le2\}$. Since $\|\nabla\tilde\kappa_m\|_{L^1}\lesssim2^m$ and $\|\delta_h^2\tilde\kappa_m\|_{L^1}\lesssim\min(1,2^m|h|)^2$, \eqref{propK} gives, for $Y\in\{L^1,\mathcal{K}\}$,
$$\|\nabla\Delta_mf\|_Y\lesssim2^m\|\Delta_mf\|_Y,\qquad \|\delta_h^2\Delta_mf\|_Y\lesssim\min(1,2^m|h|)^2\|\Delta_mf\|_Y,$$
and $\|\Delta_mf\|_\mathcal{K}\lesssim2^{\frac m2}\|\Delta_mf\|_{L^1}$ by \eqref{bernsteinK}. Hence, with $f=\langle X\rangle^{\frac12}u_0$,
$$\begin{aligned}\sum_{l\ge0}2^{\frac{3l}2}\sup_{|h|\le2^{-l}}\|\delta_h^2f\|_\mathcal{K}&\lesssim\sum_{m\ge0}2^{\frac m2}\|\Delta_mf\|_{L^1}\sum_{l\ge0}2^{\frac{3l}2}\min(1,2^{m-l})^2\\&\lesssim\sum_{m\ge0}2^{2m}\|\Delta_mf\|_{L^1},\end{aligned}$$
since $\sum_l2^{\frac{3l}2}\min(1,2^{2(m-l)})\lesssim2^{\frac{3m}2}$. The same computation in $L^1$ gives the bound $\|f\|_{B^{3/2}_{1,1}}$, and $\sum_l2^{\frac{3l}2}2^{-2l}<\infty$, which proves the first part of \eqref{sumvarpi}; the second part is bounded by $C\|f\|_{B^2_{1,1}}$ in the same way. We now prove \eqref{moduluscommon}. Since $u_{0,n}=\varrho_{\varepsilon_n}\ast(c\,\langle X\rangle^{\frac12}u_0)$ with $c:=\vartheta(\cdot/n)\langle X\rangle^{-\frac12}$, and $\|c\|_{W^{2,\infty}}\lesssim1$ uniformly in $n$, the bound \eqref{productmodulus} with $f=\langle X\rangle^{\frac12}u_0$, together with $\|\varrho_\varepsilon\ast f\|_Y\le\|f\|_Y$ and the commutation of $\delta_h^2$ with convolutions, gives $\|\delta_h^2u_{0,n}\|_Y\lesssim|h|^2+\varpi(|h|)\lesssim\varpi(|h|)$, since $\varpi(r)\ge r^2$. Similarly, the identity \eqref{weightconv} with $\theta=\frac12$, and the bound \eqref{productmodulus}, applied with $c=\mu_Z$ and then with $c=\vartheta(\cdot/n)$, give $\|\delta_h^2(\langle X\rangle^{\frac12}u_{0,n})\|_{L^1}\lesssim\varpi(|h|)$. The bounds of first order in \eqref{moduluscommon} follow in the same way from the second part of \eqref{sumvarpi}.\\

\noindent{\bf Step 3:} Bounds on $\Omega$. By Step 1 and Lemma \ref{lemmagreenop} (iii), there are $R_0\ge1$ and $\Lambda$ such that, for $n$ large, the operators $T_k$ of $u_{0,n}$ satisfy $\|T_k^{-1}\|\le\Lambda$ on the set $\Omega=\{|k|>R_0\}\cup\{|k_2|<R_0^{-1}\}$ of Lemma \ref{lemmagreenop} (iii); we remove the finitely many other indices $n$, which does not affect Steps 1 and 2. Fix $n$ and $k\in\Omega\setminus\mathbb{R}$, and write $u:=u_{0,n}$ and $\chi:=\chi_n(k;\cdot)$, where $\chi_n$ is the eigenfunction \eqref{defchi} of $u_{0,n}$, extended to $\mathbb{C}\setminus\mathbb{R}$ by Theorem \ref{thmgrin}. Let $h\in\mathbb{R}^2$ and $e\in\{1,i\}$.

By \eqref{derivativeschi}, \eqref{dkchi}, the equations of Lemma \ref{lemmadifferences} (iii) and \eqref{moduluscommon}, the functions $\chi$ and $\partial_e\chi$ and their first derivatives in $X$ are bounded, uniformly in $n$ and $k\in\Omega\setminus\mathbb{R}$; hence $\|\delta_h\chi\|_{L^\infty}+\|\delta_h\partial_e\chi\|_{L^\infty}\lesssim|h|$, and also $\|\delta_hu\|_\mathcal{K}\lesssim|h|$. Lemma \ref{lemmadifferences} (ii) with $h'=h$, applied to $g=\chi-1$, gives $\|\delta_h^2\chi\|_{L^\infty}\lesssim\|\delta_h^2u\|_\mathcal{K}+|h|^2\lesssim\varpi(|h|)$. By \eqref{productrule}, $\|\delta_h^2(u\chi)\|_{L^1}\lesssim\varpi(|h|)$, and Lemma \ref{lemmadifferences} (ii), applied to $g=\partial_e\chi$ with $(f_1,f_2)=(0,u\chi)$, gives $\|\delta_h^2\partial_e\chi\|_{L^\infty}\lesssim\varpi(|h|)$. By \eqref{productrule} and \eqref{productmodulus}, for every function $b$ on $\mathbb{R}^2$ with $\|b\|_{W^{2,\infty}}\le1$, the functions
$$\Phi\in\big\{u\chi,\ u\,\partial_e\chi,\ b\,\langle X\rangle^{\frac12}u\chi\big\}$$
satisfy $\|\Phi\|_{L^1}\lesssim1$ and $\|\delta_h^2\Phi\|_{L^1}\lesssim\varpi(|h|)$, uniformly in $n$, $k\in\Omega\setminus\mathbb{R}$ and $b$. By \eqref{fouriersecond},
\begin{equation}
\label{fourierhalf}
|\hat\Phi(z)|\lesssim\min\Big(1,\varpi\Big(\frac\pi{|z|}\Big)\Big),\qquad z\in\mathbb{R}^2\setminus\{0\}.
\end{equation}

{\it Size.} If $k\in A_j\cap\Omega$ with $j\ge1$, then $|\zeta(k)|^2=\langle \zeta(k)\rangle^2-1\ge4^{j-1}$, and \eqref{defa}, \eqref{fourierhalf} with $\Phi=u\chi$ and the monotonicity of $\varpi$ give $|a_n(k)|\lesssim\varpi(2^{3-j})$. For $j=0$, $|a_n|\lesssim1$.

{\it Modulus.} Let $k\in A_j$ and $k'\in\mathbb{C}$ with $k_2k'_2>0$ and $0<\delta:=|k'-k|\langle k\rangle\le\frac1{16}$, and assume that the segment $[k,k']$ is contained in $\Omega$. Let $z:=\zeta(k)$, $z':=\zeta(k')$ and $\nu:=z'-z$, so that $|k'-k|\le\delta$ and $|\nu|\le8\delta\le\frac12$. By \eqref{defa}, since $\operatorname{sgn}(k_2)=\operatorname{sgn}(k_2')$,
$$a_n(k')-a_n(k)=-i\operatorname{sgn}(k_2)\Big(\widehat{\big(u(\chi_n(k';\cdot)-\chi)\big)}(z')+\widehat{\big(u\chi\,(e^{-iX\cdot\nu}-1)\big)}(z)\Big).$$
By Theorem \ref{thmgrin}, $\chi_n(\cdot;X)$ is $C^1$ on $\mathbb{C}\setminus\mathbb{R}$, with the partial derivatives $\partial_1\chi_n$ and $\partial_i\chi_n$ given by \eqref{dkchi} on $\Omega\setminus\mathbb{R}$. Hence $s\mapsto\chi_n(k+s(k'-k);X)$ is $C^1$ on $[0,1]$, with derivative $\operatorname{Re}(k'-k)\,\partial_1\chi_n(k+s(k'-k);X)+\operatorname{Im}(k'-k)\,\partial_i\chi_n(k+s(k'-k);X)$. Integrating in $s$ and applying \eqref{fourierhalf} with $\Phi=u\,\partial_e\chi_n(k+s(k'-k);\cdot)$, the first term is $O\big(|k'-k|\min(1,\varpi(\pi/|z'|))\big)$. In the second term we write
$$e^{-iX\cdot\nu}-1=|\nu|^{\frac12}\langle X\rangle^{\frac12}\,b_\nu(X),\qquad b_\nu(X):=\frac{e^{-iX\cdot\nu}-1}{|\nu|^{\frac12}\langle X\rangle^{\frac12}} .$$
Since $|e^{-iX\cdot\nu}-1|\le\min(2,|\nu||X|)\le(2|\nu||X|)^{\frac12}$, we have $|b_\nu|\le\sqrt2$, $|b_\nu(X)|\le(|\nu|R)^{\frac12}$ for $|X|\le R$, and a direct computation gives $\|b_\nu\|_{W^{2,\infty}}\lesssim1$ for $0<|\nu|\le1$. By \eqref{fourierhalf} with $\Phi=b\,\langle X\rangle^{\frac12}u\chi$, $b=b_\nu/\|b_\nu\|_{W^{2,\infty}}$, and by the direct bound $|\widehat{b_\nu\langle X\rangle^{\frac12}u\chi}|\le\frac1{2\pi}\|\chi\|_{L^\infty}\int|b_\nu|\langle X\rangle^{\frac12}|u|\,dX$, the second term is $O\big(|\nu|^{\frac12}\min(\varpi(\pi/|z|),\Upsilon(|\nu|))\big)$, where
$$\Upsilon(s):=\sup_{n}\ \sup_{0<|\nu|\le s}\int_{\mathbb{R}^2}|b_\nu|\,\langle X\rangle^{\frac12}|u_{0,n}|\,dX .$$
For every $R\ge1$, the bounds on $b_\nu$ give
$$\Upsilon(s)\le(sR)^{\frac12}\sup_n\|\langle X\rangle^{\frac12}u_{0,n}\|_{L^1}+\sqrt2\sup_n\int_{\{|X|>R\}}\langle X\rangle^{\frac12}|u_{0,n}|\,dX .$$
By \eqref{tightmoment}, choosing $R$ large and then $s$ small shows that the nondecreasing function $\Upsilon$ tends to zero at $0$. If $j\ge2$, then $|z|\ge2^{j-1}$ and $|z'|\ge|z|-\frac12\ge2^{j-2}$. Altogether, since $\varpi$ is nondecreasing,
\begin{equation}
\label{modulusomega}
|a_n(k')-a_n(k)|\lesssim\begin{cases}\delta\,\varpi(2^{4-j})+\delta^{\frac12}\min\big(\varpi(2^{3-j}),\Upsilon(8\delta)\big),& j\ge2,\\ \delta+\delta^{\frac12}\,\Upsilon(8\delta),& j\le1.\end{cases}
\end{equation}

\noindent{\bf Step 4:} Bounds on the compact set $K:=\{|k|\le R_0,\ |k_2|\ge R_0^{-1}\}$. We have $(\mathbb{C}\setminus\mathbb{R})\setminus K=\Omega\setminus\mathbb{R}$. By \eqref{sumvarpi}, $\varpi(2^{-l})\lesssim2^{-\frac{3l}2}$ for $l\ge0$, and $\varpi$ is bounded on bounded sets, so that $\varpi(2^{3-j})\lesssim2^{-\frac{3j}2}$ for $j\ge1$. Hence Step 3 gives $|a_n|\lesssim\langle \zeta\rangle^{-\frac32}\le F_{\frac34,\frac34}$ on $\Omega\setminus\mathbb{R}$, and $\mathcal{I} F_{\frac34,\frac34}$ is bounded by Lemma \ref{lemmaweights} (i). By Step 1, Lemma \ref{lemmabootstrap} applies with $CF_{\frac34,\frac34}$ in place of $F$ and with $\theta=\frac12$. Let $K':=\{|k|\le R_0+1,\ |k_2|\ge(2R_0)^{-1}\}$. By Lemma \ref{lemmabootstrap} (i), the coefficients $a_n$ are uniformly bounded, and by Lemma \ref{lemmabootstrap} (ii), applied to the compact set $K'$, the nondecreasing function
$$\Upsilon_{K'}(s):=\sup_n\ \sup_{k,k'\in K',\ 0<|k'-k|\le s}\frac{|a_n(k')-a_n(k)|}{|k'-k|^{\frac12}}$$
tends to zero as $s\to0$; it is finite for every $s>0$, by \eqref{littleholder} and the uniform bound on $a_n$. Let $\delta_*:=\min(\frac1{16},(2R_0)^{-1})$, and let $k,k'$ be as in Step 3 with $\delta\le\delta_*$, but such that the segment $[k,k']$ is not contained in $\Omega$. Then $[k,k']$ meets $K$, and since $|k'-k|\le\delta\le\delta_*$, both $k$ and $k'$ belong to $K'$. Since $\langle k\rangle\ge1$,
\begin{equation}
\label{moduluscompact}
|a_n(k')-a_n(k)|\le|k'-k|^{\frac12}\,\Upsilon_{K'}(|k'-k|)\le\delta^{\frac12}\,\Upsilon_{K'}(\delta).
\end{equation}
Finally, $\langle \zeta\rangle$ is bounded on $K'$, so that $K'\subset A_0\cup\dots\cup A_{j_1}$ for some $j_1\ge1$.\\

\noindent{\bf Step 5:} Conclusion. By Step 4, and since the coefficients $a_n$ are uniformly bounded and $\langle \zeta\rangle$ is bounded on $K$, $|a_n|\le C_*\langle \zeta\rangle^{-\frac32}$ on $\mathbb{C}\setminus\mathbb{R}$ for some $C_*$ independent of $n$. Let $C_1\ge1$ be larger than the implicit constants of Steps 3 and 4, and set, for $j\ge0$ and $\delta\in(0,\delta_*]$,
$$\begin{aligned}d_j(\delta):=C_1\,2^{\frac{3j}2}\Big(&\big(\delta^{\frac12}\varpi(2^{4-j})+\min\big(\varpi(2^{3-j}),\Upsilon(8\delta)\big)\big)\1_{\{j\ge2\}}\\&+\big(\delta^{\frac12}+\Upsilon(8\delta)+\Upsilon_{K'}(\delta)\big)\1_{\{j\le j_1\}}\Big).\end{aligned}$$
By \eqref{modulusomega} and \eqref{moduluscompact}, the second bound of \eqref{hypshell2} holds; for instance, for $j\ge2$ and $[k,k']\subset\Omega$, \eqref{modulusomega} gives $|a_n(k')-a_n(k)|\le C_1\delta^{\frac12}\big(\delta^{\frac12}\varpi(2^{4-j})+\min(\varpi(2^{3-j}),\Upsilon(8\delta))\big)\le\delta^{\frac12}2^{-\frac{3j}2}d_j(\delta)$. The functions $d_j$ are nondecreasing. Each $d_j(\delta)$ tends to zero as $\delta\to0$, and $d_j(\delta)\le C_12^{\frac{3j}2}\big(\varpi(2^{4-j})+\varpi(2^{3-j})\big)+C\1_{\{j\le j_1\}}$, which is summable in $j$ by \eqref{sumvarpi}; by dominated convergence, $\sum_jd_j(\delta)\to0$ as $\delta\to0$. This proves (i). Finally, by \eqref{hypshell2}, the functions $a_n$ are uniformly bounded and equicontinuous on every compact subset of $\mathbb{C}\setminus\mathbb{R}$, and the Arzel\`a--Ascoli theorem, with a diagonal argument, gives (ii).
